window.EKOKUMA_DEVVENEDIK03 = [
{
  "id": "venedik-sebep-1171-tutuklama",
  "tur": "sebep-sonuc",
  "teyit": "teyitli",
  "yayin_adayi": true,
  "ic_not_teyit": "Marco Pozza'nın Vitale Michiel maddesi (DBI, İtalyanca) baştan sona okundu. Pozza'nın 'Venedik anlatısı' ve 'Bizans anlatısı' diye özetlediği, kendisi okunmayan vakayiname açıklamaları karttan çıkarıldı.",
  "baslik": "1171: Bizans'taki Venedikliler neden bir anda tutuklandı?",
  "olay": [
    "1171-03-12|Manuel"
  ],
  "kisa": "İmparator Manuel'in emriyle Venedikliler hapsedildi, mallarına el kondu. İlişkiler yıllardır geriliyordu; Venedik'in cevabı ise kendi dogesinin sonunu getirdi.",
  "metin": "12 Mart 1171'de Bizans imparatoru I. Manuel Komnenos, imparatorluk topraklarındaki Venedik yurttaşlarının tutuklanmasını ve mallarına el konmasını ansızın emretti. Venedikliler hazırlıksız yakalandı, çok sayıda kişi hapsedildi. Kurtulanlar azdı: bir bölümü çeşitli yerlerde yakalanmaktan kaçabildi, İstanbul'daki bir grup da tüccar Romano Mairano'nun gemisine binip imparatorluk gemilerinden sıyrılarak Akkâ'ya ulaştı. Olay birçok küçük tüccar için iktisadî yıkım oldu.\n\n■ GERGİNLİK BİRİKİYORDU\nSorun yeni değildi. Daha 1150'lerde Manuel, Venediklilerin Bizans ekonomisinde fazla ağırlaşan payını dengelemek için Cenevizlilere önemli ticaret ayrıcalıkları tanımıştı. Sonraki yıllarda Manuel İtalya'da saldırgan bir siyaset izledi ve Venedik'in Adriyatik'teki başlıca ticaret rakibi Ancona'yı destekledi. Venedik de imparatorun Macaristan'a açtığı savaşa katılmadı.\n\n1167 sonunda Doge Vitale Michiel, Normanlarla yeni bir savaş çıkarsa askerî yardım isteyen Bizans elçilerini geri çevirdi. Ertesi yıl, büyük olasılıkla, oğullarını Bizans karşıtı bir cephede evlendirdi; 1168'de de Bizans'ın müttefiki Ancona'ya bir cezalandırma seferi yaptı. Yine de ipler henüz tam kopmamıştı.\n\nPozza'ya göre tutuklamanın sebepleri bütünüyle aydınlanmış değil.\n\n■ VENEDİK'İN CEVABI\nHaber gelince önce İstanbul'a elçi gönderip temkinli davranmak düşünüldü, ama savaş yanlıları ağır bastı. Eylül 1171'de dogenin komutasında 100 kadırga denize açıldı. Donanma Eğriboz adasının merkezini kuşattı. Oradaki Bizans komutanı, İstanbul'a elçi gönderilirse el konan malların geri verileceğine güvence verdi. Venedikliler kışı Sakız'da geçirdi ve elçi üstüne elçi yolladı; sonuç alamadılar.\n\nBu arada gemilerde salgın çıktı ve kısa sürede bin kadar adam öldü. Bir imparatorluk filosu yaklaşınca Venedikliler 1172 Nisanında yer değiştirdi, ama hastalık peşlerini bırakmadı. Sonuç alınamayacağı anlaşıldıkça hoşnutsuzluk büyüdü ve doge dönüş emri verdi. Bizans gemileri onları yol boyunca rahatsız etti.\n\n■ BEDELİ DOGE ÖDEDİ\nFilo yenilmiş ve utanmış halde döndü; salgın şehre de yayıldı. 28 Mayıs 1172'de bir halk toplantısında ağır eleştirilere uğrayan ve danışmanlarınca yalnız bırakılan Michiel, Marco Casolo adlı bir saldırganca ağır yaralandı ve kısa süre sonra öldü. Saldırgan sonradan idam edildi. Yerine geçen Sebastiano Ziani, tayinle değil seçimle başa gelen ilk doge oldu.\n\n■ KAYNAK NE KADARINI SÖYLÜYOR\nOkunan biyografi gerginliğin adımlarını sıralar, ama tutuklama emrinin tek bir sebebini göstermez. Zarar gören birçok küçük tüccarın aradan uzun yıllar geçtikten sonra bile tazminat alamadığını da belirtir. Bizans tarafının kendi anlatısı bu kartta yer almıyor.",
  "kesinlik": "tartismali",
  "kaynak": "Marco Pozza, \"Michiel, Vitale\", Dizionario Biografico degli Italiani c. 74 (2010), İtalyanca, https://www.treccani.it/enciclopedia/vitale-michiel_(Dizionario-Biografico)/",
  "ic_not": "Gün (12 Mart 1171) kaynakla uyumlu. Maddenin dayandığı vakayinameler ve belgeler okunmadı. Tutuklu sayısı verilmiyor. Evlilikler için Pozza 'probabilmente nel 1168' der. Ceneviz mahallesi saldırısı ve öteki taraf açıklamaları yalnız vakayiname özeti olarak geçtiği için çıkarıldı; Bizanslı yazarların kendi metinleri bu turda okunmadı.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{ id:"venedik-antlasma-1177-venedik-barisi", tur:"antlasma",
  teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Pozza (DBI, Ziani) ve Brezzi-Piazza (Enciclopedia dei Papi, III. Alexander) ham tam metinden okundu; karta yalnız maddelerin kendi anlatısı alındı. Ziani maddesindeki vakayiname alıntısı alınmadı.",
  baslik:"Venedik Barışı 1177: papa ile imparator buluştu, ev sahibi ne kazandı?",
  olay:["1177-07-24|Venedik Barışı"],
  kisa:"Yıllar süren bir kilise bölünmesi Venedik'te kapandı. Ama bu barış herkesle yapılmadı ve her soruyu çözmedi.",
  metin:"1159'da kardinaller papalık seçiminde bölündü: bir yanda III. Alexander, öbür yanda IV. Victor adını alan rakibi vardı. İmparator Friedrich Barbarossa rakip tarafı destekledi. Victor ölünce yerine başka karşı papalar geçti ve bölünme yıllarca sürdü. Kuzey İtalya şehirleri de imparatora karşı direniyordu.\n\n" +
    "■ MASAYA GİDEN YOL\n" +
    "Friedrich'in Legnano yenilgisinden sonra görüşmeler yeniden başladı. 4 Kasım 1176'da Anagni'de bir ön anlaşmaya varıldı. İmparator böylece papa ile şehirleri birbirinden ayırmayı başarmış, aralarındaki ilişkiyi de bozmuştu. Genel durumu açıklığa kavuşturmak için bir kongre toplanacaktı; uzun tartışmalardan sonra yer olarak Venedik seçildi. Alexander 9 Mart 1177'de Vieste'den gemiye bindi ve önce Zara'ya uğradı.\n\n" +
    "■ NE İMZALANDI\n" +
    "Mayısta Venedik'te papa, imparator, Kuzey İtalya şehirlerinin temsilcileri ve Sicilya Normanlarının heyeti bir araya geldi. Görüşmeler temmuza uzadı. 24 Temmuz'da barış yapıldı, 15 Ağustos'ta onaylandı. Ancak barış yalnız papa ile Friedrich arasındaydı. Lombardiya şehirleriyle altı yıllık bir ateşkesten öteye gidilemedi. İki asıl taraf arasında bile bölünme döneminin din adamlarının akıbeti ve Roma Kilisesi'ne ait malların kesin sınırı açık bırakıldı.\n\n" +
    "Yine de kilise bölünmesi kapandı. Friedrich papanın ayağını öptü ve at binerken ona seyislik etme yükümlülüğünü yerine getirdi.\n\n" +
    "■ EV SAHİBİNİN PAYI\n" +
    "Venedik'in başında 1172'de seçilen Doge Sebastiano Ziani vardı. Selefinin Bizans'a karşı silahlı siyaseti çökmüştü. Ziani geniş bir diplomasi yürüttü: Lombardiya Birliği'nde kalırken Barbarossa'ya da yaklaştı; 1173'te imparatorluk tarafının Ancona kuşatmasını donanmasıyla destekledi, kuşatma sonuç vermedi. 1177'de Venedik, Alman imparatorluğundan eski ticaret ayrıcalıklarını daha elverişli koşullarla yeniletti. Venedik ticaretine ilk kez yalnız İtalya Krallığı'nda değil, bütün imparatorlukta tam vergi muafiyeti öngörüldü.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Ziani'nin biyografisi kongreyi dogenin siyasetinin en parlak sonucu sayar. Papa hakkındaki ansiklopedi maddesi ise Alexander'ın sabırlı ve ihtiyatlı taktiğinin açık bir başarı kazandığını, Avrupa'da mücadelenin manevî galibi olarak göründüğünü belirtir. Şehirlerin kaygısı da anlatının parçasıdır: papa onlara ihanetle suçlanamaz, ama imparatorun iki müttefiki ayıran hamlesi çok ustacaydı.",
  kesinlik:"kesin",
  kaynak:"Marco Pozza, \"Ziani, Sebastiano\", Dizionario Biografico degli Italiani c. 100 (2020), https://www.treccani.it/enciclopedia/sebastiano-ziani_(Dizionario-Biografico)/ · Paolo Brezzi - Andrea Piazza, \"Alessandro III\", Enciclopedia dei Papi (2000), https://www.treccani.it/enciclopedia/alessandro-iii_(Enciclopedia-dei-Papi)/",
  ic_not:"24 Temmuz 1177 kaynakla uyumlu. Antlaşma metni (MGH) okunmadı. Ziani maddesi ayrıcalık yenilemesine yalnız yıl verir; barışla aynı belge olduğu yazılmadı. Piazza ek bölümü eski Rolando kimliği hakkında düzeltme getirir; karta girmedi." },

{ id:"venedik-teknik-duka-altini", tur:"teknik-bilimsel",
  teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Rösch (DBI, Giovanni Dandolo) ham tam metinden okundu; karta yalnız maddenin kendi anlatısı alındı. Soy kütüğü ve sonraki tarih yazımı bahisleri alınmadı.",
  baslik:"Venedik'in ilk altın dukası zor bir dogeliğin içinden çıktı",
  olay:["1284-10-31|Duka"],
  kisa:"Büyük bir ticaret şehri, altın sikkeyi ilk kez 1284'te bastı. Üstünde dogenin kendisi vardı, ama ayakta değil, diz çökmüş hâlde.",
  metin:"Venedik altın parayı ilk kez 1284'te benimsedi. Duka ya da zecchino (bu ikinci ad basıldığı darphaneden, Zecca'dan gelir) 40 soldo değerindeydi. Bu da iki \"grosso lirası\"na karşılık geliyordu.\n\n" +
    "■ SİKKEDE NE VARDI\n" +
    "İlk dukalar, Doge Giovanni Dandolo'yu diz çökmüş olarak, İncil yazarı Aziz Markos'un elinden sancağı alırken gösteriyordu. Şehrin en yüksek görevlisi böylece sikkede, koruyucu azizin önünde yer alıyordu.\n\n" +
    "■ NE İŞE YARADI\n" +
    "Altın sikke, daha büyük tutarların elden ele dolaşmasını kolaylaştıran bir ödeme aracıydı. Venedik bu araca Floransa'dan sonra kavuştu.\n\n" +
    "■ PARAYI BASAN DOGE\n" +
    "Dandolo daha önce Cenova'ya elçi gitmiş, 1274-1276 arasında Akkâ'da Venedik'in Suriye'deki baş temsilciliğini yapmıştı. 25 Mart 1280'de doge seçildi. Dönemi sakin geçmedi. İstriya'da savaş hükûmeti boyunca sürdü; bazı kıyı şehirleri boyun eğdirildi, ama çatışma ancak sonraki dogeliğde bitti.\n\n" +
    "Papalıkla da kavga çıktı. Venedik 1281'de Anjou Kralı Charles ve Fransa Kralı Philippe ile birlikte Bizans'a karşı, adına haçlı seferi denen bir harekât tasarlamaya girişmişti. Sicilya'daki Vespers ayaklanması Anjou gücünü etkisiz bıraktı; Venedik de bu arada İstanbul ile ilişkisini onarıp ittifak kurdu. Doge, Grado patriğine ve ona bağlı din adamlarına sefer için vaaz vermeyi yasaklayınca Papa IV. Martinus Cumhuriyet'e din yasağı koydu. Yasak 1286'da kaldırıldı.\n\n" +
    "Savaş yükü kamu maliyesini zorladı. 1285'te güçlü bir deprem birçok yapıyı yıktı, can kaybına yol açtı; kısa süre sonra yüksek su depolardaki pek çok malı mahvetti. Erzak sıkıntısı çekilince doge devlet stoklarından ucuza gıda sattırdı.\n\n" +
    "Aynı yıllarda yönetimde yenilik arandı: yasalar gözden geçirildi, büyük makamların ıslahı için hukukçulardan bir komisyon kuruldu. Brenner yolu da Orta Avrupa ticareti için iyileştirilmeye çalışıldı. Dandolo 2 Kasım 1289'da öldü.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Dogenin biyografisi sikkenin yılını, değerini, ilk tasvirini ve işlevini verir. Basım kararının gününü, altının nereden geldiğini ve ayarını anlatmaz.",
  kesinlik:"kesin",
  kaynak:"Gerhard Rösch, \"Dandolo, Giovanni\", Dizionario Biografico degli Italiani c. 32 (1986), https://www.treccani.it/enciclopedia/giovanni-dandolo_res-cf80ef38-87eb-11dc-8e9d-0016357eee51_(Dizionario-Biografico)/",
  ic_not:"Kronoloji maddesinin günü 31 Ekim 1284; okunan madde yalnız yıl verir, gün karta yazılmadı. Basım kararı metni, ağırlık ve ayar için kaynak okunmadı. Treccani genel 'ducato' sayfası ham indirmede metin vermedi." },

{ id:"venedik-savas-curzola-1298", tur:"savas-hikayesi",
  teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Nuti (DBI, Lamba Doria) ham tam metinden okundu. Vakanüvisten vakanüvise değişen gemi ve kayıp sayıları ile Doria'nın oğluna dair sonraki gelenek karta alınmadı.",
  baslik:"Curzola 1298: sayıca üstün Venedik donanması nasıl kuşatıldı?",
  olay:["1298-09-08|Curzola deniz bozgunu"],
  kisa:"Venedik filosu kalabalıktı ve ilk vuruşu başarılı oldu. Öğleye doğru ise amiral gemisinin sancağı düşmüştü.",
  devlet:"venedik", taraf:["venedik","ceneviz"],
  tarih_metin:"7 Eylül 1298",
  yer:"Curzola (Korçula) adası açıkları, Dalmaçya",
  taraflar:[{ad:"Venedik",komutan:"Andrea Dandolo"},{ad:"Cenova",komutan:"Lamba Doria"}],
  oncesi:"Venedik, Doğu Akdeniz pazarlarında Cenova'nın amansız rakibi hâline gelmişti. 1298'de Cenova'da halk kaptanlarından biri olan Lamba Doria'nın komutasına bir donanma verildi. Görünürdeki amaç Aragonlu II. Jaime'ye, kardeşi Federico ile mücadelesinde destek olmaktı; asıl hedef ise Venedik'e ağır bir darbe vurmaktı. Amiralin bunda kişisel çıkarı da vardı: oğulları Bizans ülkesinde ve Karadeniz'deki Ceneviz kolonilerinde kârlı bir ticaret yürütüyordu.\n\n" +
    "Yolculuk kolay geçmedi. Donanma yaz sonuna doğru yola çıktı, ikmal için Messina'ya uğradı, Puglia kıyıları açığından Adriyatik'e girdi. Dalmaçya'ya geçerken fırtına gemileri dağıttı; Doria'yı yalnız 20 gemi izleyebildi ve bunlarla Antivari limanına sığındı. Kadırgaların çoğu yeniden toplanınca Dalmaçya kıyılarını yağmalamaya girişti, Curzola'yı ele geçirdi ve orada durdu. Yaptıklarıyla yetindiği için mi, düşman donanmasını beklemek için mi durduğu belli değil.",
  akis:"6 Eylül'de Andrea Dandolo komutasındaki Venedik donanması göründü. Yüz kadar kadırgası vardı ve sayı üstünlüğünü kullanmaya niyetliydi. Ertesi sabah savaş uzaktan atışlarla başladı. Venedikliler, karşı dizilişin yarısını yok etmek için Cenevizlilerin sağ kanadına yüklendi. İlk saldırı sonuç verdi: on Ceneviz kadırgası ağır hasar gördü.\n\nAma Ceneviz sol kanadı paniğe kapılmadı. Ustaca bir sarma hareketiyle Venedik gemilerini çevirdi. Dar alan ve kabarık deniz, Venediklilerin çemberden çıkmasını engelledi. Çaresiz savunma öğleye kadar sürdü. Amiral gemisinin sancağı düşünce yenilgi korkusu yayılmaya başladı.",
  sonuc:"Venedik donanmasının kaybı muazzam oldu: Amiral Dandolo esir düştü ve canına kıydı, pek az gemi kurtulabildi, ötekiler ele geçirildi ya da batırıldı. Ölü sayısı da çok yüksekti.\n\nZafer Cenevizlilere de pahalıya mal oldu. Doria, Venedik devletinin kalbine yürüme imkânı olduğu hâlde geri döndü. Böylece zaferle elde edilen sonuçlar boşa gitti. Ele geçirilen kadırgaları yaktı ve 6 Ekim'de Cenova'ya vardı. Cumhuriyet ona San Matteo meydanındaki bir sarayı armağan etti. Matteo Visconti'nin öncülüğünde yürüyen barış görüşmeleri, 25 Mayıs 1299'da imzalanan anlaşmayla sonuçlandı.",
  tartisma:"■ KAYNAK NE KADARINI SÖYLÜYOR\nDoria'nın biyografisi geri dönüşün sebebini kesin söylemez. Kendi filosunun ağır bedel ödemiş olmasını olası neden sayar; savunmasız kalan Cenova'da karşıt Guelf kesiminin ani bir darbesinden duyulan kaygıyı da ihtimal olarak ekler. Curzola'daki bekleyiş için de iki ihtimali yan yana bırakır.",
  kesinlik:"kesin",
  kaynak:"Giovanni Nuti, \"Doria, Lamba\", Dizionario Biografico degli Italiani c. 41 (1992), https://www.treccani.it/enciclopedia/lamba-doria_(Dizionario-Biografico)/",
  ic_not:"UYUŞMAZLIK: kronoloji maddesi 8 Eylül 1298; okunan madde donanmanın 6 Eylül'de göründüğünü, savaşın 7 Eylül sabahı yapıldığını yazar. Başka gün veren kaynak okunmadı. Venedik tarafının anlatısı (Andrea Dandolo'nun biyografisi) okunmadı. Marco Polo'nun esareti bu kaynakta yok, yazılmadı." },

{
  "id": "venedik-sebep-selanik-1423-1430",
  "tur": "sebep-sonuc",
  "teyit": "teyitli",
  teyit_kapsam:"bolum",
  "yayin_adayi": true,
  "ic_not_teyit": "Bu turda okunanlar: Melek Delilbaşı'nın Belleten makalesi (Türkçe, tam metin ve dipnotlar); Giuseppe Gullino, 'Le frontiere navali' (İtalyanca) Selânik savaşını anlatan alt bölümü (bölümün tamamı değil). Delilbaşı'nın vakanüvislerden ve kodekslerden aktardığı sayılar, konuşmalar ve belge sözleri karta alınmadı; Senato kararlarının içeriği makalenin kendi anlatısı olarak verildi.",
  "baslik": "Venedik'in yedi yıllık Selânik'i: aldığı şehri neden elinde tutamadı?",
  "olay": [
    "1430-03-29|Selânik"
  ],
  "kisa": "Bizans despotu, koruyamadığı Selânik'i Venedik'e bıraktı. Yedi yılın hikâyesinde abluka, açlık, tutulmayan sözler ve reddedilen bir büyük darbe var.",
  "metin": "1423'te Selânik el değiştirdi. Osmanlı ablukası altındaki şehri savunamayan Despot Andronikos onu Venedik'e bıraktı.\n\n■ ARKA PLAN\nSelânik XIV. yüzyılın sonunda Osmanlıların eline geçmiş, 1403'te Süleyman Çelebi tarafından Bizans'a geri verilmişti. Delilbaşı'na göre Andronikos'un önerisinde şehrin kendi geleneğine göre yönetilmesi, Rum başpiskopos ile din adamlarının görevde kalması ve halkın gitmekte ya da kalmakta serbest olması gibi şartlar vardı. Venedik, Sultan II. Murad'a da bir açıklama yapacaktı: şehri almasalar despot onu başka Hristiyanlara verecekti.\n\nBu bir satış mıydı? Delilbaşı konunun tartışmalı olduğunu belirtir. 1423 tarihli Senato talimatı, temsilcilere despota gelir fazlasından yıllık pay vaat etme yetkisi veriyordu; paranın ödendiğini gösteren bir karar ise bilinmiyor.\n\n■ SAVAŞ\nMurad bu gelişmeyi kendi toprağına tecavüz saydı. Venedik elçisi Nicolò Zorzi tutuklandı ve savaş açıkça ilan edilmeden yedi yıl sürdü. Venedik, Gullino'ya göre, genellikle oyalayıcı bir yol izledi: bir yandan donanmayla Gelibolu'yu baskı altında tuttu, öte yandan haraç önererek barış aradı. 1425'te amiral Fantino Michiel Kassandra, Platamon ve Kavala gibi yerleri ele geçirdi; yine de barış çıkmadı. 1428'de elçi Giacomo Dandolo padişaha gitti; Selânik'in teslimi gündeme gelince tutuklandı ve hapiste öldü.\n\n■ ŞEHRİN İÇİ\nAbluka altındaki şehir aç kaldı; Venedik, Girit ve öteki sömürgelerinden buğday göndermek zorundaydı. Delilbaşı, halkın Venedik yanlıları ile Türk yanlıları diye ikiye ayrıldığını anlatır. Venedikli yöneticiler anlaşmaya uymayınca ve tutumları sertleşince göç arttı, Türk yanlıları güçlendi. 1429'da Venedik'e giden bir heyetin istekleri bu çaresizliği gösterir: halk, isteyenin malını elden çıkarıp gidebilmesini, buğday gönderilmesini, asker takviyesini ve fazla vergilerin önlenmesini istiyordu.\n\n■ 29 MART 1430\nII. Murad 26 Mart'ta ordusuyla şehrin önüne geldi. 28 Mart'ta Venedikliler limandaki gemilerini korumak için surlardaki okçularını geri çekti; halk onların kaçtığını sanınca gece surların çoğu boşaldı. Şehir 29 Mart'ta düştü. Gullino, Venedik'in savunmasının çok zayıf kaldığını, ocak ayında Senato'da önerilen büyük ve pahalı bir darbenin de masrafı yüzünden reddedildiğini yazar. 4 Eylül 1430'da Edirne'de imzalanan barışla Venedik Selânik üzerindeki Osmanlı egemenliğini tanıdı; İnebahtı, İşkodra ve Leş için ise haraç ödeyerek buralardaki tutunuşunu güvenceye aldı.\n\n■ KAYNAK NE KADARINI SÖYLÜYOR\nİki yazar iki farklı pencere açıyor. Gullino Venedik'in temkinli ve masraf hesaplayan savaşını, Delilbaşı ise şehirdeki açlığı ve yönetime duyulan tepkiyi öne çıkarır. Şehrin kaybını tek bir sebebe bağlamak yerine, abluka, iç bölünme ve sınırlı savunmayı birlikte düşünmek gerekir.",
  "kesinlik": "kesin",
  "kaynak": "Melek Delilbaşı, \"Selânik'in Venedik İdaresine Geçmesi ve Osmanlı-Venedik Savaşı (1423-1430)\", Belleten 40/160 (1976), s. 573-588, belleten.gov.tr/tam-metin/1431/tur (Türkçe) · Giuseppe Gullino, \"Le frontiere navali\", Storia di Venezia (Treccani, 1996), bölüm 2, treccani.it/enciclopedia/le-frontiere-navali_(Storia-di-Venezia)/ (İtalyanca)",
  "ic_not": "29.03.1430 iki kaynakla uyumlu. Venediklilerin şehre varışı Delilbaşı'da (Morosini kodeksine göre) 14 Eylül 1423, Gullino'da devralma 24 Eylül 1423; metne yalnız yıl yazıldı. Satış sorunu: Delilbaşı dipnotu bir Bizans kroniğinin bedel kaydını, bunu reddeden ve savunan araştırmacıları sayar; bunlar okunmadı. 1428 elçiliğindeki karşılıklı sözler kronik aktarımı olduğu için alınmadı. Fetih sonrası iskân ve cami dönüşümleri bu iki kaynakta anlatılmadığı için karttan çıkarıldı.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{
  "id": "venedik-savas-korfu-1537",
  "teyit": "teyitli",
  teyit_kapsam:"bolum",
  "yayin_adayi": true,
  "ic_not_teyit": "Bu turda okunanlar: Elvin Otman'ın Bilkent doktora tezinin (2018, İngilizce) özeti ile 3.2.1 ve 3.2.3 alt bölümleri (Korfu'ya giden yol ve kuşatma; tezin tamamı değil); Giuseppe Gullino, 'Le frontiere navali' (İtalyanca) 1537-1538 anlatımı ve ilgili dipnot. Tezin adıyla vakanüvislere atfettiği rakamlar karta alınmadı.",
  "tur": "savas-hikayesi",
  "devlet": "venedik",
  "taraf": [
    "venedik",
    "osmanli"
  ],
  "baslik": "Korfu 1537: adaya inen büyük Osmanlı kuvveti neden geri döndü?",
  "olay": [
    "1537-08-25|üçüncü savaşın"
  ],
  "kisa": "Karaya asker ve top çıkarılmış, surların bir kısmı yıkılmıştı. Yine de kısa süre sonra saldırı durduruldu. Üstelik bir araştırmaya göre Korfu seferin ilk hedefi bile değildi.",
  "tarih_metin": "1537 Ağustos sonu – Eylül (Otman: 25 Ağustos çıkarma, 6 Eylül saldırıların sonu; Gullino: 26 Ağustos varış, 15 Eylül kuşatmanın kaldırılması)",
  "yer": "Korfu Adası, Adriyatik'in girişi",
  "taraflar": [
    {
      "ad": "Venedik (adayı savunan taraf)",
      "komutan": "Girolamo Pesaro (denizde başkomutan) · ada savunmasındaki subaylar Luigi da Riva ve Simon Leone"
    },
    {
      "ad": "Osmanlı",
      "komutan": "Kanûnî Sultan Süleyman; Üçüncü Vezir Lütfi Paşa; Kaptanıderya Barbaros Hayreddin Paşa; Sadrazam Ayas Paşa"
    }
  ],
  "oncesi": "Venedik 1386'dan beri Korfu'ya sahipti. Ada, Dalmaçya'daki Venedik topraklarını ve lagün şehrine gidip gelen deniz yolunu gözetiyordu; bu yüzden iyi tahkim edilmişti.\n\n1537 seferi Fransa ile ortak bir İtalya harekâtı olarak tasarlanmıştı. Donanma mayısta Lütfi Paşa komutasında Avlonya'ya doğru yola çıktı; Barbaros da katıldı. Kanûnî 17 Mayıs'ta kara ordusuyla İstanbul'dan ayrıldı. Ordu ile donanma temmuz ortasında Avlonya'da buluştu ve Lütfi Paşa Habsburg yönetimindeki Apulia'ya saldırmakla görevlendirildi. Fransız ordusu beklenen yerde görünmedi.\n\nBu sırada denizde gerilim yükseldi. Venedik gemileri Osmanlı gemilerine saldırdı; padişahın isteğini ileten Yunus Bey'in gemisi kovalandı ve elçi tutsak düştü. 22 Temmuz'da Andrea Doria bir Osmanlı kadırga grubuna saldırdı. Sultan ve komutanları Venedik'in Habsburglarla gizlice anlaştığı sonucuna vardı. Otman'a göre Korfu 1537 için baştan planlanmış bir hedef değildi; Apulia'daki hayal kırıklığı ile bu saldırılar onu hedefe dönüştürdü.",
  "akis": "■ ÇIKARMA\n25 Ağustos'ta adaya 25.000 asker ve 30 top geçirildi. Dört gün sonra Ayas Paşa, Mustafa Paşa ve Rumeli beylerbeyi de kuvvetleriyle katıldı. Padişah kara ordusuyla adanın karşısındaki Butrint'e geçti. Gullino ise donanmanın 26 Ağustos'ta Korfu önünde görüldüğünü ve Lütfi Paşa komutasında 25.000 adam çıkardığını yazar.\n\n■ KALENİN ÖNÜNDE\nTeslim çağrısına Korfulular top ateşiyle karşılık verdi. Osmanlı topları surları kısmen yıktı. Köyler, evler ve çarşı yakıldı; halk tahkimli kalelere sığındı, sığınamayanlar akıncıların eline düştü. Savunmadaki Venedik subayları uzun bir direnişe erzak ve cephanenin yetmeyeceğinden kaygılıydı. Venedik Senatosu papadan ve Doria'dan yardım istedi; Doria ise olası bir Fransız saldırısına karşı Cenova'ya yelken açtı. Gullino iki Osmanlı saldırısının püskürtüldüğünü, adanın tahkimatının da kısa süre önce güçlendirildiğini belirtir.",
  "sonuc": "Otman'a göre padişah, savaş mevsiminin sona erdiğini, şiddetli yağmurların ve salgın hastalıkların askere zarar vermeye başladığını gerekçe göstererek harekâtı bitirdi. Lütfi Paşa ile Barbaros fethin tamamlanmak üzere olduğunu söyleyip onu vazgeçirmeye çalıştı. Saldırılar 6 Eylül'de durdu; adadaki bütün kuvvetler dokuz gün içinde boşaltıldı. Gullino kuşatmanın 15 Eylül'de ansızın kaldırıldığını yazar. Venedik'te haber coşkuyla kutlandı. Ertesi yıl müttefik Hristiyan donanması Korfu'da toplandı.",
  "tartisma": "■ KAYNAK NE KADARINI SÖYLÜYOR\nÇekilmenin nedenine iki yazar farklı yerden bakıyor. Otman mevsimi, yağmuru ve hastalığı gerekçe olarak aktarıyor. Gullino ise ihtiyat payıyla, Fransızlarla işbirliğinin güçleşmeye başlamasını olası neden olarak anıyor. İki tarih de birbirini dışlamak zorunda değil: saldırıların durması ile adanın tümüyle boşaltılması ayrı günlerdir; Otman'ın dokuz günlük boşaltması Gullino'nun gününe uzanır.",
  "kesinlik": "tartismali",
  "kaynak": "Elvin Otman, The Crescent, the Lion and the Eagle: Re-analyzing the Ottoman Apulian Campaign and Attack on Corfu (1537) in the Context of Ottoman-Habsburg Rivalry, doktora tezi, İhsan Doğramacı Bilkent Üniversitesi (2018), s. 103-121, repository.bilkent.edu.tr/items/da153a1c-ddf5-4e47-b388-845b5c609a87 (İngilizce) · Giuseppe Gullino, \"Le frontiere navali\", Storia di Venezia (Treccani, 1996), bölüm 8, treccani.it/enciclopedia/le-frontiere-navali_(Storia-di-Venezia)/ (İtalyanca)",
  "ic_not": "Kronoloji maddesi 1537-08-25 Otman'ın çıkarma günüyle uyumlu; Gullino 26 Ağustos verir. '6 Eylül + dokuz gün = 15 Eylül' bağlantısı bu kartın hesabıdır, iki yazar birbirine gönderme yapmaz. Otman 25.000 asker/30 top için dipnotta Danişmend ve bir ansiklopedi maddesini, bitiş günü için Feridun Bey münşeatındaki sefer günlüğünü gösterir (bunlar ayrıca okunmadı; tezin kendi anlatısı olarak alındı). Korfu halkının tutsak sayısı vakanüvis aktarımı olduğu için, nüfus düşüşü sayıları Braudel aktarımı olduğu için yazılmadı. Korpás (Tarih Dergisi 76) kuşatmayı 'ağustos sonunda, yaklaşık üç hafta' diye anlatır.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{ id:"venedik-mimari-doge-sarayi-1577", teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Üç DBI maddesi (Beltramini, Petrecca, Maggio) tam okundu; karta yalnız maddelerin kendi anlatısı alındı. Temanza-Zorzi tartışması, Da Ponte'nin dilekçesi ve Chatsworth çizimi atfı aktarım olacağı için çıkarıldı.",
  tur:"mimari",
  baslik:"Yanan Doge Sarayı için Palladio bambaşka bir bina önerdiğinde ne oldu?",
  olay:["1577-05-20|yangını"],
  kisa:"Cumhuriyetin kalbi yandı. Dönemin en ünlü mimarlarından biri, yapıyı antik üsluba göre kökten yenilemeyi önerdi. Venedik'in kararı ise eskisinden yana oldu.",
  metin:"20 Aralık 1577'de çıkan yangın, Venedik Doge Sarayı'nın bir kanadını harap etti. Büyük Konsey Salonu ile Scrutinio (oylama) Salonu yok olanlar arasındaydı. Rıhtıma ve Piazzetta'ya bakan kanatların üst iki katı gitmişti.\n\n" +
    "■ İKİNCİ YANGIN\nSaray daha önceki yaralarını bile sarmamıştı. Mayıs 1574'te başka bir yangın, aralarında Senato salonunun da bulunduğu odaları yakmıştı. Onarımda Palladio, Giovanni Antonio Rusconi ve devletin yapı ustabaşılarından Antonio da Ponte görev aldı. Bu işler tam bitmeden ikinci ve daha ağır yangın geldi.\n\n" +
    "■ ÖNCE KONSEYE YER\nİlk sorun pratikti: Büyük Konsey nerede toplanacaktı? Da Ponte, Palladio ve iki başka ustabaşından görüş istendi; yanıt 27 Aralık'ta verildi. Ardından sıra sarayın kendisine geldi. Da Ponte ile birlikte çok sayıda usta ve mimara danışıldı. Senato 16 Ocak 1578'de üç görevli atadı. Bu görevliler, aralarında Da Ponte ile Palladio'nun da bulunduğu daha dar bir mimar grubundan ayrıntılı yazılı görüş istedi.\n\n" +
    "■ PALLADIO'NUN ÖNERİSİ\nPalladio yapının antik üsluba uygun biçimde köklü olarak yeniden yapılmasını önerdi. Palladio'yu destekleyenlerin başında, onunla uzun yıllardır çalışan Barbaro ailesinden Marcantonio Barbaro geliyordu.\n\n" +
    "■ KARŞI SIRALARDAN BİRİ\nTartışmayı izleyenlerden biri, ne zengin ne güçlü bir soylu aileden gelen Francesco Molino'ydu. Yargı kurulu Quarantia'ya seçildiği için Senato'ya girebiliyor, sarayın yeniden yapımıyla ilgili görüşmelerde bulunuyordu. Palladio ile hamisi Barbaro'nun görüşlerine karşı çıktı. Sonunda sarayın eski haliyle onarılmasına karar verilince buna sevindi.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\nYangının günü, Palladio'nun köklü yenileme önerisi ve eski halin korunması yönündeki sonuç açık. Okunan üç yaşamöyküsü ise Senato'nun karar gününü ve oyların dağılımını vermiyor. Kararda kimin sözünün ağır bastığını da bu metinlere dayanarak söylemiyoruz.",
  kesinlik:"kesin",
  kaynak:"Guido Beltramini, \"Palladio, Andrea\", Dizionario Biografico degli Italiani c. 80 (2014), treccani.it/enciclopedia/andrea-palladio_(Dizionario-Biografico)/ · Mauro Petrecca, \"Da Ponte, Antonio\", Dizionario Biografico degli Italiani c. 32 (1986), treccani.it/enciclopedia/antonio-da-ponte_(Dizionario-Biografico)/ · Silvia Maggio, \"Molino, Francesco\", Dizionario Biografico degli Italiani c. 75 (2011), treccani.it/enciclopedia/francesco-molino_(Dizionario-Biografico)/",
  ic_not:"KRONOLOJİ UYUŞMAZLIĞI: bağlanan madde 1577-05-20 günlü; Beltramini ve Petrecca yangını 20 Aralık 1577 olarak verir (iki madde aynı gün). Mayıs yangını 1574'tedir (Petrecca: 11 Mayıs 1574). Maddenin günü düzeltilmeli. Petrecca 1574 yangınında salonları üçüncü katta, Beltramini ikinci katta gösterir (kata girilmedi). Da Ponte'nin rolü üzerine Temanza-Zorzi ayrılığı karta alınmadı." },

{ id:"venedik-sebep-correzione-1582", teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Üç DBI maddesi (Trebbi, Maggio, Preto) tam okundu; karttakiler maddelerin kendi anlatısı. Molino'nun Compendio'su ve Diedo'nun Storia'sı okunmadı, bunlardan alıntı yapılmadı.",
  tur:"sebep-sonuc",
  baslik:"Soylular üç güçlü adı seçmeyince Venedik'in güç dengesi nasıl değişti?",
  olay:["1582-01-01|Correzione"],
  kisa:"Kavga oy sandığında başladı: 1582'de Büyük Konsey, tanınmış adayları seçmeyi reddetti; ertesi yıl güçlü bir kurulun ek üyelik düzeni ortadan kalktı.",
  metin:"Ekim 1582'de Venedik Büyük Konseyi alışılmadık bir şey yaptı: Onlar Konseyi'nin “zonta” denen ek üyeliği için aday olan üç nüfuzlu soyluyu seçmedi. Bunlardan biri, deneyimli diplomat Paolo Tiepolo'ydu.\n\n" +
    "■ AYNI İSİMLER, HEP AYNI KOLTUKLAR\nTiepolo 1577'den 1581'e kadar zontaya kesintisiz seçilmişti. Aynı yıllarda başka yüksek görevleri de üstleniyordu. Tepki çeken tam da buydu: Tiepolo, Soranzo kardeşler, Foscarini ve Barbaro gibi dar bir güçlü soylular çevresi en önemli makamlarda sürekli görülüyordu. Daha küçük soylular bu çevreye karşı çıktı ve öfke, güçlü Onlar Konseyi ile onun zontasına yöneldi. Bu kurul, yüzyıllara yayılan bir süreçte Venedik yönetiminin merkezine yerleşmişti.\n\n" +
    "■ KÜÇÜK BİR SOYLUNUN GÖZÜNDEN\nVarlıklı da güçlü de olmayan bir aileden gelen Francesco Molino'nun hikâyesi bu öfkeyi anlatır. 1580-81'de Pordenone'de yöneticiyken, Onlar Konseyi'nin yetkisinin, güçlü kâtip ailesi Ottobon'u yasaya aykırı biçimde kayırmak için kullanıldığını gördü. 1582'de zontanın yeniden seçilmemesini sevinçle karşıladı.\n\n" +
    "■ SAVUNMA YETMEDİ\nSert tartışmalar başladı. Tiepolo 18 Kasım 1582'de Senato'da Onlar Konseyi'ni savunan ateşli bir konuşma yaptı. Ne onun çabası ne de yönetici çevrenin öteki üyelerinin uğraşı sonucu değiştirdi.\n\n" +
    "■ SONUÇ\n1583'te anayasal reformla Onlar Konseyi'nin zontası kaldırıldı ve Senato'nun yetkisi yeniden güçlendirildi.\n\n" +
    "Bu, eski yöneticilerin tümüyle sahneden silindiği anlamına gelmedi. Tiepolo, Senato'da yönlendirici görevlerde bulunmayı sürdürdü; sık sık Savio di Consiglio, yani hükümetin önde gelen kurul üyelerinden biri seçildi. Değişen şey her şeyden önce yetkinin hangi kurumda toplandığıydı.\n\n" +
    "Zontayı savunan görüş de kaybolmadı. 1684'te doğan Venedikli tarihçi Giacomo Diedo, 1751'de yayımlanan cumhuriyet tarihinde bu olayı anlatırken açıkça zonta yanlılarından yana tavır aldı.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\nOkunan yaşamöyküleri krizin çıkışını, iki tarafın bazı yüzlerini ve sonucunu gösteriyor. Oylamaların sayıları ve reformun bütün maddeleri bu metinlerde yok; bu yüzden onlara girmiyoruz.",
  kesinlik:"kesin",
  kaynak:"Giuseppe Trebbi, \"Tiepolo, Paolo\", Dizionario Biografico degli Italiani c. 95 (2019), treccani.it/enciclopedia/paolo-tiepolo_(Dizionario-Biografico)/ · Silvia Maggio, \"Molino, Francesco\", Dizionario Biografico degli Italiani c. 75 (2011), treccani.it/enciclopedia/francesco-molino_(Dizionario-Biografico)/ · Paolo Preto, \"Diedo, Giacomo\", Dizionario Biografico degli Italiani, treccani.it/enciclopedia/giacomo-diedo_(Dizionario-Biografico)/",
  ic_not:"Madde günü 1582-01-01 (yıl hassasiyeti); kaynak krizi Ekim 1582'de başlatır, reformu 1583'e koyar. Madde başlığı 'yetkilerinin kısılması': kaynak zontanın 1583'te kaldırılmasını ve Senato yetkisinin geri verilmesini yazar. OKUNMADI: M.J.C. Lowry, The reform of the Council of Ten, 1582-3, Studi Veneziani 13 (1971); DBI Nicolò Contarini." },

{
  "id": "venedik-tartisma-rialto-banco-1587",
  "teyit": "teyitli",
  teyit_kapsam:"bolum",
  "yayin_adayi": true,
  "ic_not_teyit": "İki konuşmanın kendisi, Lattes'in 1869 neşrinden (İtalyanca/Venedik dili, taranmış metin) okundu: birincinin s. 118-123'ü, ikincinin s. 140-151 dolayı. Taramada birinci konuşmanın sonraki sayfaları görünmüyor; o bölüme dair iddia karta alınmadı. Gino Benzoni'nin Tommaso Contarini maddesi (DBI) baştan sona okundu.",
  "tur": "tartisma",
  "baslik": "Devlet banka kurmalı mı? Venedik'te aynı ada bağlanan iki zıt konuşma",
  "olay": [
    "1587-04-01|Banco"
  ],
  "kisa": "Bir metin paranın düzeni için devletin elini istiyor, öteki devletin bu işe bulaşmamasını. İkisi de aynı Venedikli soylunun adıyla yayımlandı.",
  "metin": "Büyük bir ticaret şehrinde her ödemede sikke saymak zaman alır. Banka defterine yazılan bir satır ise parayı bir hesaptan ötekine geçirir. Peki o defteri kim tutmalıydı: özel bankerler mi, devlet mi?\n\n28 Aralık 1584'te kamu bankası kurulmasına ve özel bankaların kaldırılmasına karar verildi. Venedik'in ilk kamu bankası olan Rialto Meydanı Bankası (Banco della Piazza di Rialto) ise 11 Nisan 1587'de doğdu. Soylu Tommaso Contarini'nin adıyla iki zıt konuşma metni kalmıştır.\n\n■ EVET DİYEN METİN\nKonuşmacı önce ticareti över: ticaret, birbirinden çok uzak ülkelerden oluşan dünyayı tek bir şehir gibi birleştirir. Böyle bir trafik, yazı bankası olmadan yürüyemez. Her alışverişte para sayılsa işlerin çoğu aksar; oysa kalem defterde kıpırdadığı anda alan da satan da işini görmüş olur. Noter, tanık, senet gerekmez.\n\nBaşka büyük pazarlar tüccarların karşılıklı güveniyle hesaplaşabiliyordu. Ama Venedik'te Floransalısı, Cenevizlisi, Rumu, Ermenisi, Yahudisi bir aradaydı; dilleri ve inançları ayrı insanlar birbirine böyle güvenemezdi. Bu şehre kamu otoritesi gerekliydi. Özel bankaların iflasları da gözler önündeydi: soylu evler sönmüş, kızlar çeyizsiz, dullar yardımsız, yetimler desteksiz kalmıştı.\n\n■ HAYIR DİYEN METİN\nİkinci metne göre ticaret yararlıdır, ama hükümdara yakışmaz. Onun iki asıl işi halkı yönetmek ve savaşı yürütmektir. Devlet başkalarının parasına kasadarlık ederse herkes o parayla iş çevirdiğini düşünecektir.\n\nÜstelik özel bankayı batıran nedenler kamu bankasında da vardır: dostlara kolaylık, istekler, çıkar ilişkileri. Ne kadar sert olursa olsun hiçbir yasa zimmeti önleyemez; para tutan dairelerde bunun örnekleri ortadadır. Defterde tek bir kalem darbesiyle uydurma alacaklı yaratılabilir. Yolsuzluk savaş sırasında ortaya çıkarsa ne olur? Herkes parasını geri ister, devlet ise tam o anda para aramaktadır. Konuşmacıya göre özel bir iflasta zamanla ve mahkeme yoluyla bir şeyler kurtarılabilir; parayı devlet alırsa her şey yitebilir.\n\n■ KİM, NE ZAMAN KONUŞTU\nMetinleri 1869'da yayımlayan Lattes onları Contarini'nin konuşmaları diye sunar; ilkinin başlığında 28 Aralık 1584'te Senato'da görüşülüp kabul edildiği yazılıdır. Contarini'nin biyografisini yazan Gino Benzoni ise bu konuşmaların gerçekten söylenip söylenmediğini bilmenin güç olduğunu belirtir. Ona göre iki metin, bir kararın artılarını ve eksilerini tartmak için 1584 ile 1587 arasında yazılmış özenli alıştırmalar olabilir. İkinci metnin Contarini'ye aitliğine itiraz da edilmiştir; Benzoni itirazın kanıtlanmadığını söyler.\n\n■ BANKA NASIL BAŞLADI\nBenzoni'ye göre bankanın ilk yıllarında mevduat ile kasadaki para birbirine eşitti. Kurum o dönemde, karşıtın korktuğu suistimallere düşmeden bir ödeme aracısı olarak kaldı. Sorun zamanla başka yerden gelecekti: niteliği düşük sikkelerin de mevduat olarak kabul edilmesinden.\n\n■ KAYNAK NE KADARINI SÖYLÜYOR\nİki metin bir tartışmanın iki ucunu gösterir; Senato'da kimin hangi savla ikna olduğunu göstermez. Bankanın sonraki yılları da bu kartın dışında kalıyor.",
  "kesinlik": "tartismali",
  "kaynak": "Elia Lattes, La libertà delle banche a Venezia dal secolo XIII al XVII... con due orazioni (Milano 1869), s. 118-123 ve 140-151 (birinci ve ikinci konuşma), İtalyanca, https://archive.org/download/lalibertdelleba00contgoog/lalibertdelleba00contgoog_djvu.txt · Gino Benzoni, \"Contarini, Tommaso\", Dizionario Biografico degli Italiani c. 28 (1983), İtalyanca, https://www.treccani.it/enciclopedia/tommaso-contarini_(Dizionario-Biografico)/",
  "ic_not": "Madde günü 1587-04-01; Benzoni bankanın doğuşunu 11 Nisan 1587 verir (düzeltme adayı: 1587-04-11). Taranmış metin harf tanıma hataları içerir; konuşmalardan sözcüğü sözcüğüne alıntı yapılmadı. İtirazı ileri süren Errera'nın eseri okunmadı, adı karta yazılmadı.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{ id:"venedik-kimdir-angelo-querini", teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"DBI Angelo Querini (Trebbi) tam okundu. Venturi'nin yorumu ve Haskell alıntısı aktarım olacağı için karta alınmadı.",
  tur:"kimdir",
  baslik:"Gece tutuklanan savcı Venedik'i nasıl ikiye böldü? Angelo Querini",
  olay:["1755-01-01|Querini"],
  kisa:"Görevi hukuku gözetmek olan bir soylu, devletin en korkulan kurullarından biriyle çatıştı ve bir gece Verona kalesine götürüldü. Ardından Büyük Konsey'de beklenmedik bir tepki doğdu.",
  metin:"1761'de bir ağustos gecesi Venedik soylusu Angelo Querini evi olarak kullandığı yerde tutuklandı ve Verona kalesine götürüldü. Tutuklanan sıradan biri değildi: o sırada Avogaria di Comun'da, yani hukuka uygunluğu gözeten savcılık benzeri kurumda görevliydi.\n\n" +
    "■ KİMDİ\nQuerini 31 Temmuz 1721'de doğdu. Ailesi, güçlü Senato aristokrasisi ile yoksul soylular arasında kalan, yargı görevlerinde bulunan kesimdendi. Genç yaşta Devlet Engizitörleri adlı güvenlik kuruluyla sürtüşmeye başladı.\n\n" +
    "■ ÇATIŞMA\n1758'de Avogaria'ya seçilince anlaşmazlık kamuya taşındı. Engizitörler onu bir itirazını geri çekmeye zorladı. 1761'de, yeniden aynı görevdeyken, yıllardır süren bir yolsuzluk davasını onun karşı görüşüne rağmen yeniden açmasını emrettiler.\n\n" +
    "Karşıtları, özellikle de engizitörler, onu halk tribünü gibi bir güç peşinde olmakla suçladı. 12-13 Ağustos 1761 gecesi tutuklandı. Hapiste sıkı gözetim altında tutulduğu için ardından kopan kavgaya katılamadı.\n\n" +
    "■ KONSEYDEKİ İSYAN\n23 Ağustos'ta Büyük Konsey, Onlar Konseyi'ne tek bir üye bile seçemedi. Yakınlarının çabası ve geniş soylu kesimlerin hoşnutsuzluğu açığa çıkmıştı. 9 Eylül'de, Onlar Konseyi için reform önerecek beş “düzeltici” (correttore) seçilmesine karar verildi.\n\n" +
    "Taraflar artık Querini yanlıları (“querinisti”) ve engizitörlerin kurulundan yana olanlar (“tribunalisti”) diye anılıyordu. Querini yanlıları yalnız iki düzeltici seçtirebildi. Querini'nin kendisini seçtirip serbest bırakılmasını sağlama girişimi de birkaç oyla başarısız oldu.\n\n" +
    "■ KİM KAZANDI\nMart-Nisan 1762'de, özellikle Marco Foscarini'nin istediği bir dizi öneri tartışılıp oylandı. Sonuçta Onlar Konseyi'nin ve engizitörlerin yetkisi özünde onaylandı. Querini hemen salınmadı. Ortalık yatışınca, Ekim 1763'te göreve gelen yeni engizitörler eskilerin korkularını geçmişte kalmış sayıp onu serbest bıraktı.\n\n" +
    "■ SONRAKİ HAYAT\nQuerini bundan sonra siyasette sınırlı bir rol oynadı. Zamanının çoğunu Padova yakınındaki Altichiero villasında geçirdi; bahçesiyle ve tarım denemeleriyle ilgilendi. 1777'de İsviçre'ye yaptığı gezide Voltaire ile buluştu. Voltaire ve Rousseau hayranıydı, masondu. Buna karşın Fransız Devrimi Jakoben cumhuriyetine dönüşünce ona düşman kesildi. 30 Aralık 1796'da Venedik'te öldü.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\nYaşamöyküsü Querini'de içten gelen bir özgürlük ve aykırılık eğilimi görür, sonraki yıllarında Aydınlanma çevreleriyle yakınlığını da anlatır. Düzelticilerle ilgili bütün önerileri tek tek aktarmaz; bu yüzden kart yalnız genel sonucu veriyor.",
  kesinlik:"kesin",
  kaynak:"Giuseppe Trebbi, \"Querini, Angelo\", Dizionario Biografico degli Italiani c. 86 (2016), treccani.it/enciclopedia/angelo-querini_(Dizionario-Biografico)/",
  ic_not:"KRONOLOJİ UYUŞMAZLIĞI: bağlanan madde 1755-01-01 günlü; kaynak tutuklamayı 12-13 Ağustos 1761'e, Correzione'yi 1761-62'ye koyar; 1755 yılında Querini'ye ilişkin böyle bir olay yazmaz (1758'de Avogaria'ya ilk seçilişi). Maddenin günü 1761 olmalı." },

{
  "id": "venedik-sebep-kara-olum-1348",
  "tur": "sebep-sonuc",
  "teyit": "teyitli",
  teyit_kapsam:"bolum",
  "yayin_adayi": true,
  "ic_not_teyit": "Alberto Tenenti'nin bölümünde (İtalyanca) Kara Ölüm'e ayrılan kısım, girişiyle ve alınan önlemlerin sonuna kadar kesintisiz okundu; bölümün sonraki yüzyıllara ayrılan kısmı okunmadı. Konsey kararları Tenenti'nin kendi anlatısıdır; arşiv kayıtları ayrıca okunmadı. Bölümün başka araştırmacılardan aktardığı ölü sayıları ve yargılar ile vakanüvis sözleri karta alınmadı.",
  "baslik": "1348'de Venedik veba karşısında ne yaptı?",
  "olay": [
    "1348-01-25|Kara Ölüm"
  ],
  "kisa": "Konseyler toplanamayacak kadar eksildi, mezarlıklar doldu. Yine de devlet durmadı; hatta yas giysisini yasaklayacak kadar ileri gitti.",
  "metin": "Veba Venedik'e 1348'in ilk haftalarında denizden, şehrin sıkı ilişki içinde olduğu hastalıklı limanlardan birinden geldi. Mart sonundan önce resmî bir karşılığına rastlanmıyor.\n\n■ İLK ÖNLEMLER\n30 Mart'ta Büyük Konsey, kamu sağlığını koruyacak yolları araştırmak üzere üç kişilik bir kurul atadı. En acil iş biriken cesetlerdi. Lagündeki uygun yerlerde yeni mezarlıklar açıldı; çukurların en az beş ayak derin olması istendi. Kimsesi ya da parası olmayan ölüler de masrafı devletçe karşılanarak şehirden çıkarıldı. Mahalle görevlileri güçlendirildi, evler denetlendi, ölüyü kapı önünde yasa ve bağışa açma âdeti yasaklandı. Şehre gelen tekneler sıkı gözetime alındı, hastaların girmesi engellenmeye çalışıldı.\n\n■ BOŞALAN SIRALAR\nHaziran ortasında Büyük Konsey, kayıplar yüzünden bazı kurulların yeter sayıya ulaşamadığını, Onlar Konseyi'nin bile tam toplanamadığını kabul etti; 22 Haziran'da işleri Senato'ya bıraktı. 10 Haziran'da görevlilerin şehirden ayrılması yasaklandı, haklı nedeni olanlar dışında. Noterlerin ölmesi ya da kaçması yazı ve vasiyet işlerini aksattı; temmuzda yerlerine yenileri atandı. 10 Temmuz'a gelindiğinde senatörlerin kayıtları salgının büyük ölçüde geride kaldığını düşündürüyor.\n\n■ ŞEHRİ YENİDEN DOLDURMAK\nİş gücü ve denizci lazımdı. Bazı mahpuslar affedildi, bazı sürgünlere dönüş yolu açıldı. Dışarıdan gelen zanaatkârlar ve çıraklar iki yıl boyunca loncalara ücretsiz alındı. Ailesiyle gelip en az iki yıl kesintisiz oturmayı üstlenenlere, şehir içi haklarını kapsayan yurttaşlık tanındı.\n\n7 Ağustos'ta Senato koyu renkli yas giysilerini, para cezası koyarak yasakladı; elli yaşını aşmış kadınlarla başka giysisi olmayacak kadar yoksul kadınlar bunun dışındaydı. Amaç yası gündelik hayattan uzaklaştırıp yerine neşeyi koymaktı.\n\n■ MİRAS KİMİN\nÖlümler büyük servetlerin vasiyetle kiliseye geçmesi demekti. 8 Temmuz'da Senato buna karşı tavır aldı ve ondalık ile benzeri vasiyet ödemelerinin doğrudan yapılmasını durdurdu. Castello piskoposuyla başlayan bu kavga onlarca yıl sürdü; anlaşma ancak 1376'da, sonraki bir piskoposla sağlandı.\n\n■ DENİZ YOLU KESİLMEDİ\nSalgın bütçeyi de sarstı; maaş kesintilerini içeren sıkı bir tasarruf düzeni kuruldu. Buna karşın Doğu limanlarına giden ticaret kadırgası seferleri yüzyıl boyunca salgınlar yüzünden neredeyse hiç kesilmedi.\n\n■ TARİHÇİLER BUGÜN NE DİYOR\nKaç kişinin öldüğü kesin bilinmiyor. Alberto Tenenti, 1997 tarihli değerlendirmesinde, eldeki araştırmaların vebanın ağırlığını her yönüyle ölçmeye henüz yetmediğini yazar. İlk darbenin etkisi, ardından gelen salgınlardan ayrıştırılmadan tartılamaz. Çoğu kamu kurumlarından çıkan belgelerde ise bir şey açıkça görülür: yönetim çökmedi, kendini yeniden toparladı.",
  "kesinlik": "tartismali",
  "kaynak": "Alberto Tenenti, \"Le 'temporali calamità'\", Storia di Venezia (Treccani, 1997), İtalyanca, https://www.treccani.it/enciclopedia/le-temporali-calamita_(Storia-di-Venezia)/",
  "ic_not": "Kronoloji maddesinin günü 25 Ocak 1348; okunan bölümde bu tarih, G. Villani'ye dayanan DEPREMİN başlangıç günüdür; vebanın Venedik'e geliş günü verilmez ('1348'in ilk haftaları'). Karantina ve lazaretto bu bölümde 1348 için anlatılmıyor. Tenenti'nin Mueller'e dayandırdığı ölü ve nüfus aralığı, 1500'e kadar süren nüfus açığı yargısı ve Lorenzo de' Monaci'nin sözü çıkarıldı. Kilise anlaşmazlığının tutarı (5.500 duka) yazılmadı. Bölümün sayfa numarası indirilen metinde yok.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{ id:"venedik-sebep-padova-carrara-1405", tur:"sebep-sonuc",
  teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Ganguzza Billanovich (DBI, Francesco Novello) ham tam metinden okundu; karta yalnız maddenin kendi anlatısı alındı. Maddedeki Pastorello ve Gatari alıntıları alınmadı.",
  baslik:"Bir zamanlar göz yumduğu Padova beyini Venedik neden yok etti?",
  olay:["1405-01-01|Padova"],
  kisa:"1390'da şehrini geri alırken Venedik ona engel olmamıştı. On beş yıl sonra aynı adam Venedik'te bir hücredeydi.",
  metin:"Francesco Novello da Carrara, Padova'nın son beyiydi. Babasının tahtı bırakmasıyla 1388'de başa geçti, ama aynı yıl Milano beyi Gian Galeazzo Visconti'nin ordusu karşısında şehri teslim etmek zorunda kaldı. Venedik o sırada Visconti'nin müttefikiydi.\n\n" +
    "■ GERİ DÖNÜŞ\n" +
    "Francesco gözetim altından kaçtı ve zorlu bir yolculukla Floransa'ya ulaştı. Venedik de artık Visconti'nin büyümesinden kaygılıydı. Görünürde tarafsız kaldı, ama Francesco'nun ilerleyişini durdurmak için somut bir şey yapmadı. Floransa'nın yardımı ve Venedik'in sessiz onayıyla Francesco 21 Haziran 1390'da Padova'ya girdi.\n\n" +
    "■ ÇATIŞMANIN KÖKÜ\n" +
    "Francesco küçük bir şehir devletiyle yetinmek istemiyor, daha geniş bir ülke kurmak istiyordu. 1402'de Gian Galeazzo ölünce fırsatın geldiğini düşündü. 1404'te müttefikleriyle Verona'ya yürüdü; kendi payına düşecek olan Vicenza ise 25 Nisan'da Venedik'e katılmayı seçti. Francesco mayısta Verona'yı da ele geçirdi.\n\n" +
    "Venedik'in kesinlikle engellemek istediği buydu. Cumhuriyetin soylu yönetimi, karadaki iktisadî çıkarlarının güvencesini arka ülkenin parçalı kalmasında görüyordu.\n\n" +
    "■ KUŞATMA\n" +
    "25 Eylül 1404'te Francesco ve müttefiki Niccolò d'Este, Limena'da Venedik kuvvetlerini yendi. Başarı geçici oldu. Aralık sonuna doğru Venedik ordusu Padova kapılarındaydı. Mart 1405'te Este beyi barışa çekildi. Francesco'nun evlilik dışı kardeşi Giacomo da şehri Venedik'e teslim etmeyi gizlice üstlendi.\n\n" +
    "Padova'da kıtlığa veba eklendi, şehir susuz kaldı. Floransa'dan gelen yardım sözü Francesco'yu son bir direnişe yöneltti. Sonunda 16 Kasım 1405'te şehri on gün içinde bırakmaya söz verdi; ertesi gece Venedik askerleri kapı nöbetçilerini kandırıp içeri girdi. Venedik Senatosu 22 Kasım'da Padova'nın teslimini kabul etti, Carrara elçilerini ise geri çevirdi.\n\n" +
    "■ HÜCREDE SON\n" +
    "Francesco ve oğlu Francesco, Venedik'in merhametine sığındı. Senato'da kimi Girit ya da Kıbrıs'a sürgün, kimi ömür boyu hapis önerdi. Tam o sırada, Francesco'nun Cumhuriyet'in gizli görüşmelerini öğrenmek için kurduğu casus ağı ortaya çıktı. Bu keşif, Carrara yandaşlarının komploları ve yeniden toparlanmaları tehlikesiyle birleşince Venedik sert bir karardan yana ağırlığını koydu. Francesco 17 Ocak 1406'da Onlar Konseyi'nin emriyle hücresinde boğduruldu. Hapisteki oğulları birkaç gün sonra aynı sonu paylaştı.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Biyografi bu sonu daha geniş bir dönüşüme bağlar: Verona'lı Scaliger'lerin ve Carrara'ların başaramadığı bölgesel devleti Venedik kurdu ve Padova'nın 3 Ocak 1406'daki törenli bağlılığıyla Anakara egemenliğini başlattı.",
  kesinlik:"kesin",
  kaynak:"M. Chiara Ganguzza Billanovich, \"Carrara, Francesco da, il Novello\", Dizionario Biografico degli Italiani c. 20 (1977), https://www.treccani.it/enciclopedia/carrara-francesco-da-il-novello_(Dizionario-Biografico)/",
  ic_not:"Kronoloji maddesi 1405-01-01 (yıl hassasiyeti); kaynak: 16 Kasım söz, 22 Kasım Senato kabulü, 3 Ocak 1406 törenli bağlılık. 'Venedik Anakara egemenliğini başlattı' hükmü maddenindir; Venedik'in 1405 öncesi kara toprakları (Treviso) için ayrı kaynak okunmadı." },

{
  "id": "venedik-kimdir-nicolo-canal-egriboz",
  "tur": "kimdir",
  "teyit": "teyitli",
  "yayin_adayi": true,
  "ic_not_teyit": "A. Ventura'nın Nicolò Canal maddesi (DBI, İtalyanca; önceki turda indirilen Treccani metni) biyografi bölümüyle baştan sona okundu. Kuşatmanın surlar tarafı için Kocaoğlu'nun makalesi (Türkçe, bu turda indirildi) baştan sona okundu. Maddenin aktardığı Sanudo, Malipiero ve Babinger yargıları ile Kocaoğlu'nun Rizzardo'dan verdiği kayıp sayıları karta alınmadı.",
  "baslik": "Eğriboz düşerken donanma neden bekledi? Hukuk doktoru amiral Nicolò Canal",
  "olay": [
    "1470-07-12|Eğriboz'un"
  ],
  "kisa": "Venedik filosu kuşatılan şehrin birkaç mil ötesine kadar geldi. Savunmacılar işaret verdi, bazı kaptanlar saldırmak istedi. Komutan demir attı.",
  "metin": "Eğriboz, Venedik'in Doğu Akdeniz'deki topraklarının kilit noktasıydı. 1470'te onu kurtarması beklenen donanmanın başındaki adam ise denizci değildi.\n\n■ KİMDİ\n1415'te Venedik'te doğan Nicolò Canal, Padova'da edebiyat ve hukuk okudu, iki doktora aldı. Floransa, Portekiz, İstanbul ve Fransa'ya elçi atandı (İstanbul'a ikinci atanışında gidip gitmediği bilinmiyor), Brescia'yı yönetti. Fransa görevi başarısız bitti. Ocak 1469'da Senato, şaşırtıcı bir kararla onu Ege'de Osmanlılarla savaşan donanmanın başkomutanlığına getirdi. Biyografisinin yazarına göre bu göreve hiç hazır değildi.\n\n■ AİNOS BASKINI\nCanal 14 Temmuz 1469'da Trakya'daki Ainos'u (Enez) ansızın vurdu. Çoğunluğu Rum ve Hristiyan olan halk, acımasız bir yağma ve ayrım gözetmeyen bir kıyımla karşılaştı; 2000 tutsak ve 200 Rum kadın Eğriboz'a götürüldü. Venedik o sırada bunu zafer diye kutladı.\n\n■ 1470 YAZI\nHaziran başında yüzü aşkın kadırgalık Osmanlı donanması denize açıldı. Canal'in 35 kadırgası onu uzaktan izlemekle kaldı; Osmanlı askeri 15 Haziran'da adaya çıktı. Sultanın bizzat yönettiği kara ordusu da karşı kıyıya geldi ve boğaza uzun bir gemi köprüsü kuruldu. Venedik filosu Girit'e çekildi, 28 Haziran'da oradan ayrıldı, yolda oyalandı ve adaya güneyden değil kuzeyden yaklaşarak zaman yitirdi.\n\n■ SURLARIN İÇİ\nAraştırmacı Salihcan Kocaoğlu'na göre savunmanın başında Venedik yöneticisi Paolo Erizzo vardı. Savunmacılar 25 Haziran'dan başlayan saldırıları birkaç kez geri püskürttü, ama güçleri tükeniyordu. Gözleri Canal'in filosundaydı.\n\n■ 11 TEMMUZ\nŞafakta filoyu gördüler: 52 kadırga, bir büyük kadırga (galeazza), 18 gemi ve 20 binden fazla adam. Rüzgâr elverişliydi, hazırlıksız yakalanan Osmanlı gemileri dağınıktı. Biyografiye göre köprüyü yıkmak kolay olurdu. Canal ise şehre birkaç mil kala demirledi ve gün boyu kımıldamadı. Filoyu tehlikeye atmaktan çekiniyor, geride kalan kadırgaları beklemek gerektiğini söylüyordu; o gemiler savaşmaya isteksiz olduklarını belli ediyordu. Antonio Ottobon adlı bir kaptan kadırgasıyla düşman gemilerinin arasından geçip limana girdi. Girit kadırgalarının komutanları tek başlarına saldırmayı önerdi. Canal, filo toplanmadan kimsenin kımıldamasını yasakladı.\n\nSultan o gece son saldırıyı emretti. Venedik filosu şafakta demir aldığında şehir düşmüştü. Kocaoğlu, 12 Temmuz sabahı surlardan girildiğini, halkın ise sokaklara barikat kurup öğleye doğru kadar direndiğini yazar.\n\n■ SONRASI\nSenato Canal'i görevden aldı. Zincire vurulup Venedik'e getirilen amiral yargılandı ve ömür boyu Portogruaro'da oturmaya mahkûm edildi. 1483'te öldü.\n\n■ KAYNAK NE KADARINI SÖYLÜYOR\nBiyografinin hükmü ağırdır: Canal'in yasağı şehrin kaderini belirledi. Aynı madde cezanın hayli hafif olduğunu, papa af isteyince Onlar Konseyi'nin de onun adalete göre değil merhametle yargılandığı cevabını verdiğini aktarır.",
  "kesinlik": "kesin",
  "kaynak": "A. Ventura (taranmış sayfadaki imza 'VVentura'), \"Canal, Nicolò\", Dizionario Biografico degli Italiani c. 17 (1974), İtalyanca, https://www.treccani.it/enciclopedia/nicolo-canal_(Dizionario-Biografico)/ · Salihcan Kocaoğlu, \"Venedikli Başamiral Pietro Mocenigo'nun Osmanlı-Akkoyunlu Rekabetindeki Rolü\", Türk Tarihi Araştırmaları Dergisi 10/1 (2025), s. 66-80 (kuşatma: s. 68-69), Türkçe, https://dergipark.org.tr/tr/download/article-file/4383941",
  "ic_not": "Gün: Ventura 11 Temmuz şafağında filonun göründüğünü, son saldırının aynı gece yapıldığını, şafakta şehrin düşmüş olduğunu yazar; Kocaoğlu son saldırıyı 11 Temmuz'da başlatır ve 12 Temmuz sabahı surlara girildiğini yazar. Kronoloji maddesiyle (12 Temmuz) uyumlu. Kocaoğlu Canal'in başkomutanlığa seçilmesini 1468 diye verir; Ventura'nın Ocak 1469'u esas alındı.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{ id:"venedik-savas-agnadello-1509", tur:"savas-hikayesi",
  teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Pieri (DBI, Bartolomeo d'Alviano) ham tam metinden okundu; karta yalnız maddenin kendi anlatısı alındı.",
  baslik:"Agnadello 1509: iki komutan, iki plan, tek bozgun",
  olay:["1509-05-14|Agnadello"],
  kisa:"Venedik ordusunun başındaki iki adam savaşın nasıl yapılacağında anlaşamıyordu. Artçı birlik saldırıya uğrayınca bu ayrılık sahaya çıktı.",
  devlet:"venedik", taraf:["venedik","fransa"],
  tarih_metin:"14 Mayıs 1509",
  yer:"Agnadello; Venedik ordusu Treviglio topraklarından Pandino yöresine geçerken",
  taraflar:[{ad:"Venedik",komutan:"Pitigliano kontu Niccolò Orsini (başkomutan), Bartolomeo d'Alviano (ikinci komutan)"},{ad:"Fransa",komutan:""}],
  oncesi:"Bartolomeo d'Alviano 1455'te, büyük ihtimalle Todi'de doğmuş bir savaşçıydı. Küçük yapılı ve çelimsizdi, ama cüretli bir komutandı. 1508'de Cadore'de imparatorluk kuvvetlerini kuşatıp yok etti, ardından Pordenone, Gorizia, Trieste ve Fiume'yi aldı. Biyografisine göre bu parlak başarı Venedik gücünün doruğunu gösteriyor, aynı zamanda Cumhuriyet'e karşı Cambrai ittifakının birleşmesine yol açıyordu.\n\n1509'da Alviano ordunun ikinci komutanı, Pitigliano kontu ise başkomutanıydı. Alviano, Fransızlar Lombardiya'da toplanmayı bitirmeden Milano ülkesine girmek, orayı Fransa'ya karşı ayaklandırmak, bu cepheyi hızla sonuçlandırıp sonra imparatorluk güçlerine dönmek istiyordu. Pitigliano daha ihtiyatlı bir yolu doğru buluyordu: savunmada kalmak, arazi tahkimatından sonuna kadar yararlanıp Fransız hücumunu frenlemek ve uygun anda karşı saldırıya geçmek.",
  akis:"14 Mayıs'ta Venedik ordusu Treviglio topraklarından Crema yöresindeki Pandino'ya doğru ilerlerken, Alviano'nun birliklerinden oluşan artçıya Fransız öncüsü saldırdı. Alviano düşmanı püskürttü. Ama temastan sıyrılacağına rakibin üstüne gitti ve Pitigliano'dan destek istedi; destek gelmedi. Piyadeleri Gaskonyalı atıcıları, hatta İsviçrelileri de geri attı. Sonunda çevrildiler ve yok edildiler. Yüzünden yaralanan Alviano esir düştü.",
  sonuc:"Fransa kralı bu esirliğe o kadar önem verdi ki Alviano'yu dört yıl bırakmadı. Alviano tutsaklığında anılar yazdı; bunlardan bugüne bir şey kalmadı. 1513'te Venedik ile XII. Louis ittifak kurunca serbest kaldı ve Venedik ordusunun başkomutanı oldu. 1515'te Francesco I'in İsviçrelileri yendiği büyük savaşta Venedik süvarisiyle sonucun dönmesinde rol oynadı; aynı yılın ekiminde hastalanarak öldü.",
  tartisma:"■ KAYNAK NE KADARINI SÖYLÜYOR\nBiyografiyi yazan Piero Pieri bozgunu iki komutanın görüş ayrılığının sonucu sayar. Alviano'nun genel çizgisini de aynı ölçüyle değerlendirir: başkomutan ile ikinci komutan birbirini anlayıp birlikte hareket ettiğinde büyük başarı geldi, uyum olmayınca Agnadello'da olduğu gibi yenilgi. Okunan madde iki ordunun mevcudunu ve kayıplarını vermez.",
  kesinlik:"kesin",
  kaynak:"Piero Pieri, \"Alviano, Bartolomeo d'\", Dizionario Biografico degli Italiani c. 2 (1960), https://www.treccani.it/enciclopedia/bartolomeo-d-alviano_(Dizionario-Biografico)/",
  ic_not:"14 Mayıs 1509 kaynakla uyumlu. Fransız komutanın adı maddede verilmediği için boş. Pitigliano biyografisi ve 1960 sonrası literatür okunmadı; Pieri'nin hükmü tek yazarın görüşüdür. 1515 savaşı maddede Melegnano adıyla, 13-14 Eylül günleriyle geçer." },

{ id:"venedik-sebep-ferrara-savasi-1482", tur:"sebep-sonuc",
  teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Dean (DBI, Ercole I) ve Russo (DBI, Roberto Sanseverino d'Aragona) ham tam metinden okundu; karta yalnız maddelerin kendi anlatısı alındı. Dean'in Frizzi'ye ve vakanüvise dayandırdığı bahisler ile Russo'daki belge alıntıları alınmadı.",
  baslik:"Tuz, sınır ve bir papa: Venedik Ferrara'ya neden savaş açtı?",
  olay:["1482-05-03|Ferrara Savaşı"],
  kisa:"Anlaşmazlıkların çoğu eskiydi ve görüşmeyle çözülebilirdi. Bu kez masaya başka hesaplar da kondu. Savaşın sonunda Polesine Venedik'te kaldı.",
  metin:"Savaşın neden patladığını anlamak kolay değil: Ferrara dükü I. Ercole'nin biyografisini yazan Trevor Dean böyle uyarır.\n\n" +
    "■ BİRİKEN ŞİKÂYETLER\n" +
    "Venedik, Comacchio'daki yasa dışı tuz üretiminden, Rovigo Polesine'sindeki sınır sorunlarından, ticaret anlaşmalarının çiğnenmesinden ve Ferrara'daki temsilcisine kötü davranılmasından yakınıyordu. Ercole ise Venediklilerin Ferrara'da aşırı dokunulmazlıklardan yararlanmasından, kaçakçılık takibinin sertliğinden ve Ferrara mallarına konan vergilerden şikâyetçiydi. Dean'e göre bu sorunlar önceden de çıkmıştı ve siyasî irade olsaydı yine görüşmeyle çözülebilirdi.\n\n" +
    "■ DEĞİŞEN İTTİFAKLAR\n" +
    "Ercole, Napoli Kralı Ferrante'nin kızıyla evlenerek eski dost Venedik'ten uzaklaşmıştı. 1480'de Venedik papayla ittifak kurdu; Ferrara karşı kampta, Floransa, Milano ve Napoli'nin yanında kaldı. Çözümü engellemekte Venedik'in yeni müttefiki Papa IV. Sixtus'un, daha doğrusu yeğeni Girolamo Riario'nun belirleyici payı oldu. Ferrara papalık devletine bağlı bir şehirdi. Dean, Napoli'ye karşı yardım karşılığında papanın desteği olmasaydı Venedik'in böyle bir şehre savaş açmayacağını açık sayar.\n\n" +
    "■ SAVAŞ\n" +
    "Venedik daha Kasım 1481'de Polesine içine küçük tahkimatlar kurdu. 3 Nisan 1482'de deneyimli komutan Roberto Sanseverino'yu hizmetine aldı. Mayısta papa Venedik'e Ferrara'yı topraklarına katmasını önerdi. Sanseverino Po'yu hızla geçip Ercole'yi hazırlıksız yakaladı. Ficarolo bir aydan uzun direndi ve 30 Haziran'da düştü. Rovigo ağustosta alındı. Bu arada sıtma askerler arasında yayıldı, Sanseverino da ağır hastalandı. Ferrara'da ise veba görüldü, Ercole yatağa düştü.\n\n" +
    "Kasımda Venedik kuvvetleri Po'yu aşıp neredeyse şehir kapılarına kadar akınlar yaptı. Kışın denge değişti: papa Venedik'i bırakıp karşı ittifaka katıldı, Ferrara'ya yardım geldi. Savaş Lombardiya'da açılan ikinci cepheye kaydı.\n\n" +
    "■ BAGNOLO\n" +
    "Gizli görüşmeler başlayınca Ferrara'nın müttefikleri arasındaki dayanışma çözüldü. Birbiriyle de anlaşamayan Ludovico Sforza ile Calabria dükü, Venedik'in işgal ettiği her yeri geri vermesinde diretmedi. 7 Ağustos 1484'te Bagnolo'da yapılan barış Venedik'e Polesine'yi elinde tutma ve Ferrara'daki bütün ayrıcalıklarını onaylatma imkânı verdi.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Dean sonucu Ercole için gerçek bir felaket sayar: toprak kaybı, özellikle Modena ve Reggio'dan kıtlığın yol açtığı kitlesel göç, tahrip olan mal ve ekinler, ağır borç ve enflasyon. Venedik içindeki savaş tartışmaları bu iki biyografide anlatılmaz.",
  kesinlik:"kesin",
  kaynak:"Trevor Dean, \"Ercole I d'Este\", Dizionario Biografico degli Italiani c. 43 (1993), https://www.treccani.it/enciclopedia/ercole-i-d-este-duca-di-ferrara-modena-e-reggio_(Dizionario-Biografico)/ · Alessio Russo, \"Sanseverino d'Aragona, Roberto\", Dizionario Biografico degli Italiani c. 90 (2017), https://www.treccani.it/enciclopedia/roberto-sanseverino-d-aragona_(Dizionario-Biografico)/",
  ic_not:"Kronoloji maddesinin günü 3 Mayıs 1482; okunan iki madde bu günü vermez (Russo: 'mayıs başında Po geçildi'; Dean: papanın önerisi Mayıs 1482). Russo barışı 'Ağustos 1484', Dean 7 Ağustos verir. Rovigo için Russo parantezde 14 Ağustos yazar; karta yalnız ay yazıldı çünkü cümle yapısı günün neyi tarihlediği konusunda tek tanık." },

{ id:"venedik-sebep-uskok-savasi-1615", teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"Enciclopedia Italiana 'Uscocchi' (Praga, 1937) ve DBI 'Giustiniani, Pompeo' tam okundu; karttakiler maddelerin kendi anlatısı. Praga kaynakçasındaki eserler okunmadı.",
  tur:"sebep-sonuc",
  baslik:"Küçük bir sınır topluluğu Venedik ile Avusturya'yı nasıl savaşa sürükledi?",
  olay:["1615-01-01|Uskok"],
  kisa:"Başlangıçta birkaç yüz kişiydiler. Baskınları yalnız Osmanlı gemilerini değil Venedik'i de vurunca mesele Adriyatik'te bir devletler kavgasına dönüştü.",
  metin:"“Uskok” sözü Sırpça-Hırvatçada kaçıp sığınan kimse anlamındaki “uskok”tan gelir. Balkanlar Osmanlı yönetimine girdikçe ve 1526'da Macaristan yenilince, özellikle Avusturya-Macaristan askerî sınırında sığınmacı toplulukları oluştu. Bunlar savaşı çete baskınlarıyla sürdürdü.\n\n" +
    "■ SEGNA'NIN BASKINCILARI\n" +
    "İlk önemli yerleşimleri Klis kalesiydi. 1537'de oradan çıkarılınca, denizden ve karadan baskına elverişli, sarp bir kıyı kenti olan Segna'ya (Senj) sığındılar. Kâğıt üzerinde Avusturya'dan ücret alıyorlardı, ama geçimleri esas olarak yağma ve korsanlığa dayanıyordu. İki üç yüz olan sayıları, Venedik'ten sürülmüş kimselerin ve Romagna ile Lazio'dan gelen maceracıların katılmasıyla 16. yüzyılın ikinci yarısında 2000'e ulaştı. Yalnız Osmanlı kervan ve gemilerine değil, Dubrovnik'in, Papa'nın ve Venedik'in gemilerine de saldırdılar.\n\n" +
    "■ VENEDİK'İN SIKIŞMASI\n" +
    "Adriyatik'in güvenliğinden kendini sorumlu sayan Venedik, özellikle doğrudan donanmayla müdahale tehdidinde bulunan Osmanlı yönetiminin baskısı altındaydı. Diplomasi sonuç vermeyince 14 Mart 1592'de Uskoklarla mücadele için özel bir komutan atadı. Avusturya da bir ara komiser gönderdi, ama korsanlığın çevresinde örülen çıkar ağı işi yavaşlattı. Uskoklar 31 Aralık 1601 gecesi arşidüklük komiseri Giuseppe Rabatta'yı öldürdü. 1605'ten sonra baskınlar yeniden arttı. 12 Mayıs 1613'te bir Venedik kadırgasına saldırıp kaptanını öldürdüler.\n\n" +
    "■ SAVAŞ\n" +
    "1615 sonlarında Venedik komutanı Lorenzo Venier, Fiume yakınındaki Novi'de asker toplandığını öğrenince kaleye saldırıp yıktı. Ardından Graz savaş ilan etti. Venedik cephesinde komutanlardan Pompeo Giustiniani aralıkta Palmanova'dan 10.000 askerle çıktı; 19 Aralık'ta Cormons, Cervignano ve Aquileia ansızın alındı. Hedef Gradisca'yı hızla ele geçirip üç ayda arşidükün askerlerini bölgeden atmaktı. Plan tutmadı. Sıkı bir kuşatma sonuç vermedi, savaş mevzi savaşına döndü. Giustiniani Ekim 1616'da yaralanıp öldü.\n\n" +
    "■ SONUÇ\n" +
    "Savaş, Fransa ve İspanya'nın araya girmesiyle yapılan Madrid Barışı'na, 26 Eylül 1617'ye kadar sürdü. Avusturya Uskokları Hırvatistan'ın iç kesimlerine taşımayı ve gemilerini yakmayı üstlendi. Ertesi yaz antlaşma uygulandı; Segna'da kalan az sayıda Uskok Otočac ve Žumberak'a yerleştirildi, orada halka karıştı.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Topluluğu anlatan ansiklopedi maddesi 1937 tarihlidir. Bu kart onun temel olay sırasını verir; Uskokların nasıl değerlendirileceğine ilişkin sonraki araştırmaları kapsamaz.",
  kesinlik:"kesin",
  kaynak:"Giuseppe Praga, \"Uscocchi\", Enciclopedia Italiana (1937), treccani.it/enciclopedia/uscocchi_(Enciclopedia-Italiana)/ · Dario Busolini, \"Giustiniani, Pompeo\", Dizionario Biografico degli Italiani c. 57 (2001), treccani.it/enciclopedia/pompeo-giustiniani_(Dizionario-Biografico)/",
  ic_not:"Madde günü 1615-01-01 (yıl hassasiyeti); kaynaklara göre açık savaş 1615 sonunda (Aralık) başlar, 26 Eylül 1617'de biter (Praga). Busolini Mart 1616'da görüşmelerin ilerleyişi bir aylık sıkı kuşatmadan sonra durdurduğunu, Praga Gradisca kuşatmasının şubatta başladığını yazar. Praga 1937 tarihli; güncel hakemli Uskok literatürü (ör. C.W. Bracewell) OKUNMADI. TDV'de Uskok maddesi bu turda bulunamadı (yalnız bir slug denendi, arama sayfasına yönlendi)." },

{ id:"venedik-mimari-salute-longhena", teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"DBI 'Longhena, Baldassare' (Hopkins) tam okundu; Temanza alıntıları karta alınmadı. Veba salgınının kendisine ilişkin rakam ve adak kararı bu maddede olmadığı için yazılmadı.",
  tur:"mimari",
  baslik:"Salute Kilisesi'ni yapan adam neden kendini hep onunla tanıttı?",
  olay:["1630-01-01|veba"],
  kisa:"Veba yılı 1630'un sonunda açılan yarışmayı, taşçı atölyesinden yetişmiş bir Venedikli kazandı. Bu iş onun ömrünün sonraki yarım yüzyılını belirledi.",
  metin:"Venedik'in en tanınan yapılarından Santa Maria della Salute'nin mimarı Baldassare Longhena, işe kâğıt üstünde değil taş atölyesinde başlamıştı.\n\n" +
    "■ ATÖLYEDEN MİMARLIĞA\n" +
    "1596 sonunda ya da 1597 başında, büyük olasılıkla Venedik'te doğdu. Babasının taşçı atölyesinde yetişti; usta mimar Vincenzo Scamozzi'nin öğrencisi oldu. Babası ve Scamozzi 1616'da ölünce atölyenin başına geçti. Burada yalnız taş işçiliği değil, yazışma, ihale ve hesap işleri de öğrenmişti. Yaşamöyküsünün yazarı Andrew Hopkins'e göre bu birleşim onu ilk meslekten mimar tiplerinden biri yaptı.\n\n" +
    "■ VEBA VE YARIŞMA\n" +
    "1630 vebasının ardından Longhena önce Chioggia'da bir kilise için Meryem'e adanmış bir sunak işi aldı. 1630 sonunda ise Santa Maria della Salute Kilisesi'nin tasarımı ve yapımı için açılan resmî yarışmaya katıldı. İşi kazandı ve o tarihten sonra yapımın yöneticisi oldu.\n\n" +
    "■ BİR KİLİSE, BİR KARİYER\n" +
    "1630'larda yapım denetimi için görevlendirilen soylular aracılığıyla sonraki birçok müşterisini tanıdı. 1640'ta, San Marco'nun mal varlığını yöneten yüksek görevlilerin (procuratori) baş mimarlığına atandı; bu, devlet mimarlığına denk bir görevdi ve ömrünün son haftalarına kadar sürdü.\n\n" +
    "1640'ların ortasında kilisenin ana gövdesi tamamlandıkça yapının önemi daha görünür oldu. 1644'te Marco Boschini'nin bir gravürü onu kutladı. Longhena'nın ünü büyüdü, büyük aileler ondan saray istedi.\n\n" +
    "■ İÇERİDEKİ VEBA\n" +
    "1670'te kilisenin ana sunağı üzerinde çalışmaya başladı. Heykeltıraş Juste Le Court ile yapılan sunaktaki heykel grubunda Venedik ve Meryem vebayı şehirden kovar. Hopkins bu grubu 17. yüzyıl Venedik'inin en önemli iki heykel grubundan biri sayar; ikisinin de tasarımını Longhena'ya bağlar.\n\n" +
    "■ İMZADAKİ İPUCU\n" +
    "Longhena 1631'den itibaren belgelere hep “yeni kilisenin baş ustası” anlamındaki unvanla imza attı. Hopkins bunu, kilisenin başyapıtı ve hayatının en önemli işi olduğunun farkında oluşuyla açıklar. 1679'da ömrünün sonuna yaklaşırken kilisede nelerin tamamlanması gerektiğini belirtti. 18 Şubat 1682'de Venedik'te öldü.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Okunan metin bir mimarın yaşamöyküsüdür. Salgının kaç can aldığını ve kilisenin hangi törenlerle adandığını anlatmaz; bu kart da o konulara girmez.",
  kesinlik:"kesin",
  kaynak:"Andrew Hopkins, \"Longhena, Baldassare\", Dizionario Biografico degli Italiani c. 65 (2005), treccani.it/enciclopedia/baldassare-longhena_(Dizionario-Biografico)/",
  ic_not:"Bağlanan madde 'Büyük veba' (1630-01-01); kart kiliseyi/mimarı anlatır. Senato adak kararı (arama özetinde 22 Ekim 1630) ve temel atma OKUNMADI, yazılmadı. DBI 'Contarini, Nicolò' okunmadı." },

{
  "id": "venedik-sebep-kandiye-1669",
  "tur": "sebep-sonuc",
  "teyit": "teyitli",
  "yayin_adayi": true,
  "ic_not_teyit": "Elias Kolovos'un bölümü (İngilizce, hakemli, açık erişim; bölümün tamamı) ile Giuseppe Gullino'nun Francesco Morosini maddesinin (DBI, İtalyanca) metni baştan sona okundu. Kartta başka kaynaktan olgu yok.",
  "baslik": "Kandiye teslim edildiğinde geriye nasıl bir şehir kalmıştı?",
  "olay": [
    "1669-09-06|Kandiye'nin teslimi"
  ],
  "kisa": "Sakinlerin büyük çoğunluğu Venedik filosuyla gitti. Geride kalan binaları ise bir Osmanlı defteri tek tek saydı.",
  "metin": "6 Eylül 1669'da Venedik'in başkomutanı Francesco Morosini, Senato'dan önceden yetki almadan Kandiye'nin teslimi üzerinde anlaştı. Yaklaşık 25 yıl süren savaş böyle bitti.\n\n■ ANLAŞMA\nBiyografisini yazan Giuseppe Gullino'ya göre Morosini yetkisini aşmıştı. Ama askerlik bakımından çözülemeyen bir durumu da çözmüştü: Venedik için üç üs korundu, sanat hazineleri ve 1204'ten beri süren yönetimin arşivleri kurtarıldı.\n\n■ BOŞALAN ŞEHİR\nGiritli tarihçi Elias Kolovos'un anlatımıyla, teslimden sonra sakinlerin büyük çoğunluğu Venedik filosuyla şehirden ayrıldı. Kuşatan Osmanlı ordusu içeri girdi.\n\nFazıl Ahmed Paşa'nın emriyle hicrî 1080 (1669-70) yılında surların içi baştan kaydedildi. Bu defter bugün İstanbul'daki Osmanlı Arşivi'ndedir. Venedik şehrinin 55 mahallesini, kiliselerinden gelen eski adlarıyla sıralar; yapıları ve arsaları ölçüleriyle yazar, şehri terk eden eski sahiplerin adlarını da verir. Tersanede toplam on dört gemi gözü sayılmıştır.\n\n■ ADRESLER EL DEĞİŞTİRİYOR\nKatolik San Francesco manastırının kilisesi teslimden hemen sonra Sultan Mehmed Han'ın büyük camisine çevrildi. Dük Sarayı'na İbrahim Paşa yerleşti; sarayın üst katı 7 Aralık 1669'da açık artırmayla Hasan Ağa'ya 2400 kuruşa satıldı.\n\nPapa Da Rodo adlı birinin on iki odalı evine önce bir yeniçeri birliği yerleşti. Ev sonra 100 kuruşa, yeni caminin baş müezzini Mehmed Çelebi'ye satıldı.\n\n■ KALANLARDAN BİRİ\nHerkes gitmemişti. Şehirde kalan az sayıdaki Hristiyandan biri Nicolaki Castrofylaka'ydı. Defteri hazırlayan görevliye tercümanlık etti; defterdeki ev kaydına, sahibinin orada olduğu ve tercümanlık yaptığı not düşüldü.\n\nSatışlar sürdü. Defterin sonundaki 1672 tarihli buyruk, fetihten hemen sonra yazılan ev, dükkân ve bahçelerin ordu şehirdeyken isteyenlere artırmayla satıldığını bildirir. Ordu ayrıldıktan sonra da satış devam etti.\n\n■ VENEDİK'TE HESAP\nMorosini dönüşünde yargılandı; soruşturma 19 Eylül 1670'te açıldı. Yolsuzluktan itaatsizliğe uzanan suçlamalar patrisileri ikiye böldü. Büyük kasa açıkları ve işe karışan başka soylular ortaya çıktı. Senato sonunda sanıkları suçsuz ilan etti.\n\n■ KAYNAK NE KADARINI SÖYLÜYOR\nKolovos kendi yazısını defterin ön incelemesi diye tanıtır; defterin tam yayını o sırada hazırlanıyordu. Okunan iki metin teslim anlaşmasının maddelerini, şehrin nüfus sayısını ve ayrılanların nereye yerleştiğini vermiyor. Bu yüzden burada onlar üzerine hüküm yok.",
  "kesinlik": "kesin",
  "kaynak": "Elias Kolovos, \"An Ottoman Register of Venetian Candia\", Anna Valerio (ed.), Venetians and Ottomans in the Early Modern Age, Hilâl 6, Edizioni Ca' Foscari, 2018, s. 75-84, İngilizce, hakemli açık erişim, DOI 10.30687/978-88-6969-260-4/006, https://edizionicafoscari.it/media/pdf/books/978-88-6969-261-1/978-88-6969-261-1-ch-06.pdf · Giuseppe Gullino, \"Morosini, Francesco\", Dizionario Biografico degli Italiani c. 77 (2012), İtalyanca, https://www.treccani.it/enciclopedia/francesco-morosini_(Dizionario-Biografico)/",
  "ic_not": "6 Eylül 1669 kronoloji maddesiyle uyuşuyor (Gullino). Kolovos teslimi yalnız '1669 sonbaharı' diye verir. Kolovos'taki '13 Hristiyan hane reisi' sayısı yalnız cizyenin en yüksek dilimine aittir; toplam nüfus sanılmasın diye karta alınmadı. Papa Da Rodo evinin satış tarihine bağlanan derkenar günü (17 Şaban 1080 / 10 Ocak 1670) metinde satışın mı notun mu günü olduğu açık olmadığı için yazılmadı. Oda sayısı: 9 zemin + 3 üst kat.",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{
  "id": "venedik-savas-sakiz-1694-1695",
  "tur": "savas-hikayesi",
  "teyit": "teyitli",
  teyit_kapsam:"bolum",
  "yayin_adayi": true,
  "ic_not_teyit": "Tahir Sevinç'in makalesi (Türkçe, BOA belgelerine dayalı) baştan sona okundu. Katolik topluluk için Ambrosius Eszer'in makalesinin giriş bölümü (Almanca, s. 295-296) okundu; makalenin kalanı 1628-1639 yıllarını işler, karta girmez ve baştan sona okunmadı. Sevinç'in dipnotla gösterdiği Kantemir, Uzunçarşılı ve arşiv belgeleri ayrıca okunmadı; kartta makalenin kendi anlatısı olarak verildi.",
  "devlet": "venedik",
  "taraf": [
    "venedik",
    "osmanli"
  ],
  "baslik": "Sakız'ı sonbaharda alan Venedik adayı neden birkaç ay sonra yitirdi?",
  "olay": [
    "1695-02-09|Sakız"
  ],
  "kisa": "1694 sonbaharında kale anlaşmayla teslim alındı. Şubatta Osmanlı donanması geri döndü. Venedik giderken yalnız askerlerini götürmedi.",
  "tarih_metin": "Eylül 1694 – Şubat 1695",
  "yer": "Sakız Adası, Ege",
  "taraflar": [
    {
      "ad": "Venedik; Papalık, Floransa ve Malta gemileriyle",
      "komutan": "Kale Antonio Zeno'ya teslim edildi"
    },
    {
      "ad": "Osmanlı",
      "komutan": "Kalede Silâhdar Hasan Paşa; geri alışta serasker Mısırlızade İbrahim Paşa ve Mezamorto Hüseyin Paşa"
    }
  ],
  "oncesi": "Ada 1346'dan 1566'ya kadar Cenevizlilerin elindeydi. 1566'da Piyale Paşa komutasındaki Osmanlı donanması adayı aldı. Konumu yüzünden Venedik'in gözü sonraki yıllarda da üzerinden ayrılmadı. 1681'de ise Garp Ocakları korsanlarının peşindeki bir Fransız filosu şehri topa tuttu; büyük yıkım ve can kaybı oldu.\n\n■ İÇERİDEKİ GERİLİM\nTarihçi Tahir Sevinç'e göre savaşın yükü altındaki devlet, adadaki Hristiyanlardan 1694 Eylülünde ikinci bir cizye topladı ve bu büyük tepki doğurdu. Makaleye göre ada Hristiyanları kaledeki leventlerin davranışlarından yakındı. Korumayı kendilerinin üstleneceğini söyleyip bir miktar da para vererek hükümeti üç bin leventi kaldırmaya ikna ettiler. Bir süre sonra da Venediklilere adada asker olmadığını bildirdiler.",
  "akis": "■ KUŞATMA\nVenedik, Papalık, Floransa ve Malta gemilerinden oluşan 115 parçalık donanma, Osmanlı donanmasının kış için çekilmesini bekledi. Eylül 1694'te adaya 12.000 yaya ve 800 süvari çıkardı. Kaleyi 1370 askerle Silâhdar Hasan Paşa savunuyordu. Kaptanıderya Yusuf Paşa'dan istediği yardım gelmedi. Makaleye göre adanın yerli Hristiyanları da silahlanıp Osmanlı askerine arkadan saldırdı. Kaleye atılan beş yüzü aşkın top güllesi ve humbara evleri yıktı, yiyecekler yandı.\n\n■ TESLİM\nHasan Paşa kaleyi vire ile, yani anlaşmayla, Antonio Zeno'ya bıraktı. Paşa ve adadaki Müslümanlar Venedik gemileriyle Çeşme'ye taşındı.\n\n■ DENİZDEN GERİ DÖNÜŞ\nİstanbul yeni bir sefere girişti: top döküldü, barut, peksimet ve asker toplandı. 8 Şubat 1695'te Osmanlı kuvvetleri Foça önündeki adaları geçip Koyun Adaları yakınına geldi; ertesi gün Kayaburnu denen yerde demirledi. Bir süre sonra Venedik kalyonlarının yaklaştığı haberi geldi ve deniz çarpışmaları başladı. 18 Şubat'ta filolar yeniden vuruştu. Bu savaşta bir Osmanlı güllesi 55 toplu bir Venedik gemisinin cephanesine isabet etti; gemi havaya uçup battı.\n\n21 Şubat'ta Osmanlı donanması Sakız limanındaki Venedik filosuna yüklendi. Venedik gemileri kaçtı; kalede kalan 500 Venedik askeri esir alındı.",
  "sonuc": "Dönüş sessiz olmadı. Dominiken tarihçisi Ambrosius Eszer'e göre Venedikliler Şubat 1695'te adayı yerli Katolik halkın büyük bir bölümüyle birlikte terk etti. Adadaki Katolik hayatı neredeyse tümüyle çöktü; Dominikenlerin kilisesi de başka kiliselerle birlikte camiye çevrildi.\n\nSevinç'e göre Hristiyan halkın bağ, bahçe gibi mülklerine el kondu; durumu elverişsiz olanlarınki kendilerine bırakıldı. El konan mülkler sonra Hristiyan halka 470 kese akçeye (235.000 kuruş) satıldı. Zafer kazanan Mezamorto Hüseyin Paşa kaptanıderyalığa yükseltildi.",
  "tartisma": "■ NEDEN TUTUNAMADI\nSevinç, Osmanlı hazırlığının eksiksizliğine ve komutan seçimine dikkat çeker. Venedik'in aynı sırada Mora'da ve başka cephelerde de Osmanlılarla savaştığını, bu yüzden Sakız'a yeterince eğilemediğini de ekler.\n\n■ KAYNAKTAKİ PÜRÜZ\nTeslimin günü belirsiz. Makale kuşatmanın 9 Eylül'de başladığını ve Hasan Paşa'nın sekiz gün dayandığını yazar, ama teslim günü olarak 12 Ekim'i verir. İkisi birbirini tutmadığı için burada gün seçilmedi. Yerli Hristiyanların kuşatmadaki rolü de bu metinde Osmanlı tarafı üzerinden anlatılır; olayın o topluluklar içinden anlatımı okunmadı.",
  "kesinlik": "tartismali",
  "kaynak": "Tahir Sevinç, \"1695 Sakız Seferi'nde Organizasyon ve Lojistik\", SDÜ Fen-Edebiyat Fakültesi Sosyal Bilimler Dergisi, sayı 21 (Mayıs 2010), s. 59-79, Türkçe, https://dergipark.org.tr/tr/download/article-file/117923 · Ambrosius Eszer O.P., \"Ein Reformversuch im Dominikanerkonvent S. Sebastiano auf Chios (1628-1639)\", Archivum Fratrum Praedicatorum 46 (1976), s. 295-365 (kullanılan: s. 295-296), Almanca, https://heyjoe.fbk.eu/index.php/afp/article/download/12093/12094",
  "ic_not": "KRONOLOJİ: bağlama anahtarı 1695-02-09. Sevinç 9 Şubat'ı (8 Şubat'ın ertesi günü) Kayaburnu'nda demirleme günü olarak verir; ilk çarpışma için gün vermez ('bir süre sonra'). Adanın geri alınışına ilişkin metindeki gün 21 Şubat'tır (özet: deniz savaşları 21-25 Şubat). Maddenin günü ve metni gözden geçirilmeli. Özet 8 Şubat'ta İzmir'den hareket der, metin aynı gün Foça önünden geçildiğini yazar. Teslim: '9 Eylül'de başlayan kuşatma, sekiz gün' ile '12 Ekim 1694' çelişir. Makaledeki 10.000'den fazla Venedik ölüsü sayısı alınmadı. İtalyanca ikinci anlatı arandı: 14. yüzyıldaki adaş Antonio Zeno'nun DBI maddesi başka kişi; unitesi.unive.it'teki bir Venedik yüksek lisans tezi 403 verdi (okunamadı).",
  "ic_not_erisim": "ONARIM (26.11.2026): TDV ya da aktarım dayanağı çıkarıldı; kart, engel aşmayan indirme aracıyla yeniden kaynaklandırıldı."
},

{ id:"venedik-kimdir-daniele-manin", teyit:"teyitli", yayin_adayi:true,
  ic_not_teyit:"DBI 'Manin, Daniele' (Gottardi) tam okundu; Manin'in söz ve sorgu alıntıları belge aktarımı olacağı için karta alınmadı.",
  tur:"kimdir",
  baslik:"Hapisten çıkan avukat beş gün sonra nasıl cumhuriyet ilan etti?",
  olay:["1848-03-22|Arsenal'i ele geçirdi; San Marco Cumhuriyeti ilan edildi, Manin"],
  kisa:"Soyadı son dogeninkiyle aynıydı, ama soyu o aileden gelmiyordu. Daniele Manin, yasal yollarla reform isterken Venedik ayaklanmasının önderi oldu.",
  metin:"Daniele Manin 13 Mayıs 1804'te Venedik'te doğdu. Yahudi kökenli dedesi 1759'da Katolik olmuş ve âdet olduğu üzere kendisini koruyan soylu ailenin soyadını almıştı: Manin. Vaftiz babasının, Cumhuriyet'in son dogesi Ludovico Manin'in adını da benimsemişti.\n\n" +
    "■ ERKEN YETİŞEN HUKUKÇU\n" +
    "On dört yaşında Padova Üniversitesi'ne yazıldı, 1821'de hukuk diploması aldı. Babasının cumhuriyetçi görüşlerinden etkilendi. Sonraki yıllarda yayıncılık ve avukatlık yaptı. Venedik-Milano demiryolu tartışmasında savunduğu tez sonunda yenildi, ama ona tanınırlık kazandırdı.\n\n" +
    "■ YASAL MÜCADELE\n" +
    "1847'de Avusturya yönetiminden dilekçelerle ekonomik adımlar istedi; yıl sonuna doğru siyasi reform talepleri de öne çıktı. 8 Ocak 1848'deki geniş dilekçesinde ifade özgürlüğü, Yahudilerin eşit haklara kavuşması ve hukuk reformu da vardı. 18 Ocak'ta Niccolò Tommaseo ile birlikte tutuklandı. Yaşamöyküsü yazarı Michele Gottardi'ye göre devrimin gerekli olduğuna hapiste inandı; şehrin farklı kesimleri de onu önder olarak görmeye başladı.\n\n" +
    "■ BEŞ GÜN\n" +
    "17 Mart'ta serbest bırakıldı. Kalabalık onu zaferle taşıdı. Manin sükûnet çağrısı yaptı ve sivil bir muhafız birliği kurdurdu. 21 Mart'ta Milano ayaklanmasının haberi geldi. Manin'in planı, subayların, muhafızların ve tersane işçilerinin katılımıyla Arsenal'i ayaklandırmaktı. 22 Mart sabahı, işçilerin Albay Marinovich'i öldürdüğü haberi gelince artık beklemedi. Oğlu Giorgio ile Arsenal'e gitti, burayı tümüyle ele geçirdi ve “Yaşasın San Marco” sesleri arasında cumhuriyeti ilan etti. Ertesi gün geçici hükümetin başına geçti.\n\n" +
    "■ KUŞATMA VE SÜRGÜN\n" +
    "Anakaradaki Veneto toprakları aylar içinde kaybedildi. 4 Temmuz'da meclis, yönetimi Savoia temsilcilerine devretmeyi öngören Yukarı İtalya Krallığı ile birleşmeyi onayladı; Manin hükümeti bıraktı. Ağustosta ateşkesle bu dönem kapanınca yeniden iktidara geldi. 1849 nisanında ne pahasına olursa olsun direnme kararı alındı ve Manin'e geniş yetki verildi. Kolera yayılıp orduda itaatsizlik başlayınca teslimi kabul etti; teslim 22 Ağustos 1849'da imzalandı. 27 Ağustos'ta sürgüne gitti.\n\n" +
    "Paris'te İtalyanca dersleri vererek geçindi. Zamanla, ülkeyi birleştirecekse Savoia Hanedanı'nın desteklenmesi gerektiğini savundu. 22 Eylül 1857'de öldü. Naaşı 22 Mart 1868'de Venedik'e getirildi.\n\n" +
    "■ KAYNAK NE KADARINI SÖYLÜYOR\n" +
    "Gottardi, Manin'in şehirle özdeşleşmesini Risorgimento'da benzersiz bulur. Ona göre bu özdeşlik zamanla siyasi ufku dar bir şehirciliğe indirgendi ve Manin hakkındaki yargıyı da etkiledi.",
  kesinlik:"kesin",
  kaynak:"Michele Gottardi, \"Manin, Daniele\", Dizionario Biografico degli Italiani c. 69 (2007), treccani.it/enciclopedia/daniele-manin_(Dizionario-Biografico)/",
  ic_not:"22 Mart 1848 bağlanan maddeyle uyuşuyor. Kronoloji maddesindeki 'Avusturya birlikleri 26 Mart'ta çekildi' bilgisi bu kaynakta yok, karta alınmadı. Gottardi'nin özdeşleşmenin sonuçlarına ilişkin cümlesi yorumdur, adıyla verildi." }

];
